        baseMaxSpeedKmh: baseTop,
      );
      // Simulate a real 1-lap physics qualifying run on this exact circuit for every AI!
      driver.qualiTimeSec = _simulateAiQualiLap(driver);
      aiDrivers.add(driver);
    }

    poleReferenceTime = aiDrivers.map((a) => a.qualiTimeSec).reduce((a, b) => min(a, b));
  }

  /// Physics-based 1-lap qualifying simulation on the exact circuit geometry so AI times match player pace fairly!
  double _simulateAiQualiLap(AiDriver ai) {
    double dist = 0.0;
    double spd = 0.0;
    double t = 0.0;
    const double dt = 0.025;
    // Competitive pro-level qualifying pace: top bots push hard through corners & use ERS on straights
    final double qualiBaseTop = 292.0 + (ai.skill * 38.0);
    double aiErs = 100.0;

    while (dist < circuit.lapLengthMeters && t < 65.0) {
      final double kNow = _curvatureAtDist(dist).abs();
      final double kNear = _curvatureAtDist(dist + 50.0).abs();
      final double kFar = _curvatureAtDist(dist + 105.0).abs();
      final double maxK = max(kNow, max(kNear * 0.90, kFar * 0.74));
      final double gripFactor = (1.0 - (maxK * (0.155 - ai.skill * 0.048))).clamp(0.56, 1.0).toDouble();
      double desired = qualiBaseTop * gripFactor;

      if (kNow < 0.38 && kNear < 0.52 && aiErs > 4.0) {
        desired += 26.0 * ai.skill;
        aiErs = max(0.0, aiErs - 21.0 * dt);
      }

      if (desired > spd) {
        spd = min(desired, spd + (142.0 + ai.skill * 34.0) * dt);
      } else {
        spd = max(desired, spd - (265.0 + ai.skill * 60.0) * dt);
      }
      dist += (spd / 3.6) * dt;
      t += dt;
    }
    final double variance = (rng.nextDouble() - 0.40) * 0.42;
    return max(8.0, t + variance);
  }

