  /// Places all 22 cars on the actual F1 staggered starting grid based on Qualifying order!
  void startRaceFromGrid() {
    phase = SessionPhase.race;
    isPaused = false;
    raceFinished = false;
    startLightsTimer = 3.2;

    // Grid slot 1 (Pole) is furthest forward; slot 22 is furthest back.
    // Keep slot 22 at +14m past origin so nobody has negative trackDist!
    const double gridSpacing = kGridSpacing;
    for (int idx = 0; idx < qualifyingGrid.length; idx++) {
      final QualiResultEntry entry = qualifyingGrid[idx];
      final int pos = idx + 1; // 1 = Pole .. 22 = Last
      final double startDist = 14.0 + ((totalCars - pos) * gridSpacing);
      final double startLane = (pos % 2 == 1) ? -0.44 : 0.44;

      if (entry.isPlayer) {
        playerDist = startDist;
        prevPlayerDist = startDist;
        carX = startLane;
      } else if (entry.aiRef != null) {
        final AiDriver ai = entry.aiRef!;
        ai.trackDist = startDist;
        ai.prevTrackDist = startDist;
        ai.laneX = startLane;
        ai.targetLaneX = startLane;
        ai.currentSpeedKmh = 0.0;
        ai.lateralVel = 0.0;
        ai.steerTilt = 0.0;
        ai.ersCharge = 100.0;
        ai.drsOpen = false;
        ai.isBraking = false;
        ai.collisionCooldown = 0.0;
        ai.overtakeSide = 0.0;
        ai.overtakeCommitTimer = 0.0;
        ai.defenseCooldown = 0.0;
        ai.launchDelay = 0.04 + ((1.0 - ai.skill) * 0.28) + rng.nextDouble() * 0.14;
      }
    }

    speedKmh = 0.0;
    lateralVel = 0.0;
    steerAngle = 0.0;
    spinYaw = 0.0;
    controlRecoveryTimer = 0.0;
    ersCharge = 100.0;
    ersToggledOn = false;
    totalRaceTime = 0.0;
    lapStartTime = 0.0;
    bestLapTime = 999.0;
    fastLapTime = 999.0;
    hitFlash = 0.0;
    _lastLitStartLights = 0;
    _lastGear = 1;
    _engineRpm = 4200.0;
    _downshiftBlip = 0.0;
    particles.clear();
    showRadio('SALIDA DESDE P$playerGridPosition — ¡APAGADO DE SEMÁFORO!', secs: 3.2);
    notifyListeners();
  }

  int get currentLap {
    if (phase == SessionPhase.qualifying) return 1;
    // Offset by player's starting grid distance so everyone completes 5 full laps!
    final double gridStartOffset = 14.0 + ((totalCars - playerGridPosition) * kGridSpacing);
    final double racedDist = max(0.0, playerDist - gridStartOffset);
    return ((racedDist / circuit.lapLengthMeters).floor() + 1).clamp(1, totalLaps).toInt();
  }

  double get lapProgress => (playerDist % circuit.lapLengthMeters) / circuit.lapLengthMeters;
  static const List<double> _gearTops = [0.0, 96.0, 138.0, 178.0, 216.0, 252.0, 288.0, 322.0, 372.0];

  int get gear {
    if (speedKmh < 2.0) return 1;
    for (int g = 1; g <= 8; g++) {
      if (speedKmh <= _gearTops[g]) return g;
    }
    return 8;
  }

  int get rpm => _engineRpm.clamp(3800.0, 14200.0).toInt();

  void _updateEngineRpm(double dt, {required bool onGrid}) {
    _downshiftBlip *= exp(-9.5 * dt);
    if (onGrid || speedKmh < 2.0) {
      // Realistic free-revving on the starting grid with rev-limiter bounce!
      if (gasHeld && !brakeHeld) {
        _engineRpm = min(13200.0, _engineRpm + 14500.0 * dt);
        if (_engineRpm >= 12750.0) {
          _revLimiterPhase += dt * 19.0;
          _engineRpm = 12450.0 + sin(_revLimiterPhase * pi * 2.0) * 420.0;
        }
      } else {
        _engineRpm = max(4100.0, _engineRpm - 9200.0 * dt);
      }
      return;
    }

    final int g = gear;
    final double lo = _gearTops[g - 1];
    final double hi = _gearTops[g];
    final double frac = ((speedKmh - lo) / max(1.0, hi - lo)).clamp(0.0, 1.0).toDouble();
    // Wide, dramatic F1 V6 RPM sweep per gear: 7,800 -> 13,400 RPM (+600 on ERS)
    double wheelRpm = g == 1
        ? (4300.0 + frac * 9100.0)
        : (7800.0 + frac * 5600.0);
    if (ersActive) wheelRpm += 550.0;
    if (!gasHeld && !brakeHeld) wheelRpm -= 450.0;
    final double targetRpm = (wheelRpm + _downshiftBlip).clamp(3900.0, 14100.0).toDouble();
    final double followRate = targetRpm > _engineRpm ? 18.0 : 12.0;
    _engineRpm += (targetRpm - _engineRpm) * (1.0 - exp(-followRate * dt));
  }
  bool get ersActive => ersToggledOn && ersCharge > 0.5 && gasHeld && !brakeHeld;

  int get currentPosition {
    if (phase == SessionPhase.qualifying) {
      // Live projected grid position based on current pace vs Pole reference
      if (qualiElapsed <= 0.1) return 1;
      final double progress = (playerDist / circuit.lapLengthMeters).clamp(0.02, 1.0).toDouble();
      final double projectedTotal = qualiElapsed / progress;
      int faster = 0;
      for (final ai in aiDrivers) {
        if (ai.qualiTimeSec < projectedTotal) faster++;
      }
      return (faster + 1).clamp(1, totalCars).toInt();
    }
    int ahead = 0;
    for (final ai in aiDrivers) {
      if (ai.trackDist > playerDist) ahead++;
    }
    return (ahead + 1).clamp(1, totalCars).toInt();
  }

  void showRadio(String msg, {double secs = 2.4}) {
    radioMessage = msg;
    radioTimer = secs;
  }

  void spawnParticles(Color color, int count, {bool sparks = false}) {
    for (int i = 0; i < count; i++) {
      particles.add(
        TrackParticle(
          x: 0.25 + rng.nextDouble() * 0.5,
          y: 0.62 + rng.nextDouble() * 0.22,
          vx: (rng.nextDouble() - 0.5) * (sparks ? 1.65 : 0.72),
          vy: (sparks ? -0.58 : -0.22) - rng.nextDouble() * 0.45,
          life: 0.30 + rng.nextDouble() * 0.32,
          color: color,
          radius: sparks ? (2.1 + rng.nextDouble() * 2.4) : (3.0 + rng.nextDouble() * 4.2),
          isSpark: sparks,
        ),
      );
    }
  }

  double _curvatureAtDist(double dist) {
    final double prog = (dist % circuit.lapLengthMeters) / circuit.lapLengthMeters;
    return geometry.curvatureAtProgress(prog);
  }

  double _idealRacingLineX(double dist) {
    final double kNow = _curvatureAtDist(dist);
    final double kEntry = _curvatureAtDist(dist + 75.0);
    final double kFar = _curvatureAtDist(dist + 145.0);

    if (kNow.abs() > 0.45) {
      return (kNow.sign * (0.45 + (kNow.abs() / 2.9) * 0.35)).clamp(-0.76, 0.76).toDouble();
    }
    if (kEntry.abs() > 0.55) {
      return (-kEntry.sign * (0.42 + (kEntry.abs() / 2.9) * 0.30)).clamp(-0.72, 0.72).toDouble();
    }
    if (kFar.abs() > 0.85) {
      return (-kFar.sign * 0.48);
    }
    return 0.0;
  }

  /// Returns: 0 = running, 1 = qualifying finished, 2 = race finished
  int step(double dt) {
    if (raceFinished || isPaused || phase == SessionPhase.gridOverview) return 0;

    if (radioTimer > 0) {
      radioTimer = max(0.0, radioTimer - dt);
      if (radioTimer == 0) radioMessage = '';
    }

    if (startLightsTimer > 0) {
      final double prevTimer = startLightsTimer;
      startLightsTimer = max(0.0, startLightsTimer - dt);
      final double totalCountdown = phase == SessionPhase.qualifying ? 2.2 : 3.2;
      int litCount = 0;
      for (int idx = 0; idx < 5; idx++) {
        if (startLightsTimer < (totalCountdown - 0.15 - idx * (totalCountdown * 0.15))) {
          litCount++;
        }
      }
      if (litCount > _lastLitStartLights) {
        _lastLitStartLights = litCount;
        F1SoundEngine.playEvent('light');
      }
      if (prevTimer > 0.0 && startLightsTimer == 0.0) {
        F1SoundEngine.playEvent('go');
      }
      // Free-rev V6 engine on the grid while waiting for lights out!
      _updateEngineRpm(dt, onGrid: true);
      _audioUpdateAcc += dt;
      if (_audioUpdateAcc >= 0.025) {
        _audioUpdateAcc = 0.0;
        F1SoundEngine.update(
          rpm: _engineRpm,
          speed: 0.0,
          throttle: gasHeld && !brakeHeld,
          brake: brakeHeld,
          ers: false,
          offTrack: false,
          onKerb: false,
          slip: 0.0,
          active: true,
        );
      }
      notifyListeners();
      return 0;
    }

    if (phase == SessionPhase.qualifying) {
      qualiElapsed += dt;
    } else {
      totalRaceTime += dt;
    }

    for (int i = particles.length - 1; i >= 0; i--) {
      final TrackParticle p = particles[i];
      p.x += p.vx * dt;
      p.y += p.vy * dt;
      p.vy += 1.45 * dt;
      p.life -= dt;
      if (p.life <= 0) particles.removeAt(i);
    }

    prevPlayerDist = playerDist;
    final int prevLap = currentLap;

    if (brakeHeld && ersToggledOn) {
      ersToggledOn = false;
    }

    final bool ersOn = ersActive;
    if (ersOn) {
      ersCharge = max(0.0, ersCharge - 21.0 * dt);
      if (ersCharge <= 0.5) {
        ersToggledOn = false;
        showRadio('BATERÍA ERS AGOTADA', secs: 1.8);
      }
    } else {
      final double rechargeRate = brakeHeld ? 26.0 : 6.8;
      ersCharge = min(100.0, ersCharge + rechargeRate * dt);
    }

    // Player aerodynamic slipstream (only during Race when rivals are on track)
    playerInSlipstream = false;
    if (phase == SessionPhase.race && speedKmh > 150.0 && !brakeHeld) {
      for (final ai in aiDrivers) {
        final double dz = ai.trackDist - playerDist;
        if (dz > 6.0 && dz < 42.0 && (ai.laneX - carX).abs() < 0.36) {
          playerInSlipstream = true;
          break;
        }
      }
    }

    // 100% Manual Throttle & Braking (ZERO auto-gas, ZERO auto-acceleration)
    final bool effectivelyAccelerating = gasHeld && !brakeHeld;
    final double slipBonus = playerInSlipstream ? 16.0 : 0.0;
    final double maxSpeed = (ersOn ? 360.0 : 322.0) + slipBonus;

    double targetPitch = 0.0;
    if (effectivelyAccelerating) {
      final double accel = (ersOn ? 182.0 : 128.0) + (playerInSlipstream ? 18.0 : 0.0);
      speedKmh = min(maxSpeed, speedKmh + accel * dt);
      targetPitch = ersOn ? -1.0 : -0.35;
    } else if (brakeHeld) {
      speedKmh = max(0.0, speedKmh - 295.0 * dt);
      targetPitch = speedKmh > 30 ? 1.0 : 0.0;
    } else {
      // Natural engine braking & aerodynamic drag all the way down to 0 km/h
      speedKmh = max(0.0, speedKmh - (38.0 + speedKmh * 0.08) * dt);
    }

    smoothPitch += (targetPitch - smoothPitch) * (1.0 - exp(-9.0 * dt));
    final double targetFov = ((speedKmh - 140.0) / 220.0).clamp(0.0, 1.0).toDouble() + (ersOn ? 0.25 : 0.0);
    smoothFovBoost += (targetFov - smoothFovBoost) * (1.0 - exp(-5.0 * dt));

    // 100% Manual Steering (ZERO steering assist / ZERO rail-following)
    double targetSteer = 0.0;
    if (leftHeld) targetSteer -= 1.0;
    if (rightHeld) targetSteer += 1.0;
    steerAngle += (targetSteer - steerAngle) * (1.0 - exp(-14.5 * dt));

    final double realCurve = geometry.curvatureAtProgress(lapProgress);
    horizonPan = (horizonPan - realCurve * (speedKmh / 300.0) * dt * 135.0) % 2400.0;

    // Camera bank follows ONLY your manual steering input
    final double targetBank = steerAngle * 0.024;
    smoothCamBank += (targetBank - smoothCamBank) * (1.0 - exp(-8.5 * dt));

    // Real cornering physics: without manual steering input, the car goes straight off the outside of every curve!
    final double centrifugal = realCurve * (speedKmh / 145.0) * (0.75 + 0.55 * (speedKmh / 260.0));

    if (controlRecoveryTimer > 0) {
      controlRecoveryTimer = max(0.0, controlRecoveryTimer - dt);
    }

    final bool offTrack = carX.abs() > 1.02;
    final double speedSteerScale = (speedKmh / 40.0).clamp(0.0, 1.0).toDouble();
    final double steerAuthority = (offTrack ? 0.65 : 1.0) * (controlRecoveryTimer > 0 ? 0.78 : 1.0);
    final double steerForce = steerAngle * (2.65 + (speedKmh / 240.0) * 1.15) * speedSteerScale * steerAuthority;

    lateralVel += (steerForce - centrifugal) * dt * 4.6;
    final double lateralDamping = offTrack ? 2.6 : 4.4;
    lateralVel *= exp(-lateralDamping * dt);
    carX += lateralVel * dt;
    spinYaw *= exp(-5.2 * dt);

    if (offTrack) {
      // Gravel/grass rolling resistance slows naturally toward 0 km/h (never auto-accelerates!)
      speedKmh = max(0.0, speedKmh - (95.0 + speedKmh * 0.42) * dt);
      if (speedKmh > 65.0 && rng.nextDouble() < 0.42) {
        spawnParticles(const Color(0xFFC2AA82), 2);
      }
      if (carX.abs() >= 1.52) {
        final double wallSign = carX >= 0 ? 1.0 : -1.0;
        carX = wallSign * 1.52;
        if (lateralVel * wallSign > 0.35) {
          lateralVel = -wallSign * 0.22;
          spinYaw = -wallSign * 0.16;
          speedKmh = max(0.0, speedKmh * 0.58);
          hitFlash = (speedKmh / 140.0).clamp(0.35, 1.0).toDouble();
          ersToggledOn = false;
          spawnParticles(const Color(0xFFFFB300), 12, sparks: true);
          F1SoundEngine.playEvent('crash', intensity: (speedKmh / 140.0).clamp(0.45, 1.0).toDouble());
          showRadio('¡IMPACTO CONTRA EL MURO!', secs: 1.6);
        } else {
          if (lateralVel * wallSign > 0.0) lateralVel = 0.0;
          speedKmh = max(0.0, speedKmh - (75.0 + speedKmh * 0.25) * dt);
        }
      }
    }

    final double distStep = (speedKmh / 3.6) * dt;
    playerDist += distStep;

    if (hitFlash > 0) hitFlash = max(0.0, hitFlash - dt * 2.8);

    // Check Qualifying completion (1 full lap)
    if (phase == SessionPhase.qualifying) {
      if (playerDist >= circuit.lapLengthMeters) {
        completeQualifying();
        return 1;
      }
      final int qGear = gear;
      if (qGear != _lastGear && speedKmh > 35.0) {
        if (qGear > _lastGear) {
          F1SoundEngine.playEvent('upshift');
        } else {
          _downshiftBlip = 1550.0;
          F1SoundEngine.playEvent('downshift');
        }
        _lastGear = qGear;
      }
      _updateEngineRpm(dt, onGrid: false);
      _audioUpdateAcc += dt;
      if (_audioUpdateAcc >= 0.025) {
        _audioUpdateAcc = 0.0;
        final bool onKerbNow = carX.abs() > 0.88 && carX.abs() <= 1.04;
        final double tireSlip = ((steerAngle.abs() * (speedKmh / 215.0)) + (lateralVel.abs() * 0.24)).clamp(0.0, 1.0).toDouble();
        F1SoundEngine.update(
          rpm: _engineRpm,
          speed: speedKmh,
          throttle: gasHeld && !brakeHeld,
          brake: brakeHeld,
          ers: ersActive,
          offTrack: offTrack,
          onKerb: onKerbNow,
          slip: tireSlip,
          active: true,
        );
      }
      notifyListeners();
      return 0;
    }

    // Update Smart AI + Precision Swept Collisions (Race phase only)
    _updateSmartAiAndCollisions(dt);

    // Gear shift audio (distinct upshift ignition-cut pop vs downshift rev-match bark)
    final int curGearNow = gear;
    if (curGearNow != _lastGear && speedKmh > 35.0) {
      if (curGearNow > _lastGear) {
        F1SoundEngine.playEvent('upshift');
      } else {
        _downshiftBlip = 1550.0;
        F1SoundEngine.playEvent('downshift');
      }
      _lastGear = curGearNow;
    }

    _updateEngineRpm(dt, onGrid: false);

    // Stream smooth engine, tire slip & track telemetry to native DSP audio engine (~40Hz)
    _audioUpdateAcc += dt;
    if (_audioUpdateAcc >= 0.025) {
      _audioUpdateAcc = 0.0;
      final bool onKerbNow = carX.abs() > 0.88 && carX.abs() <= 1.04;
      final double tireSlip = ((steerAngle.abs() * (speedKmh / 215.0)) + (lateralVel.abs() * 0.24)).clamp(0.0, 1.0).toDouble();
      F1SoundEngine.update(
        rpm: _engineRpm,
        speed: speedKmh,
        throttle: gasHeld && !brakeHeld,
        brake: brakeHeld,
        ers: ersActive,
        offTrack: offTrack,
        onKerb: onKerbNow,
        slip: tireSlip,
        active: true,
      );
    }

    // Check Race lap / finish completion
    final double gridStartOffset = 14.0 + ((totalCars - playerGridPosition) * kGridSpacing);
    final int newLap = (((playerDist - gridStartOffset) / circuit.lapLengthMeters).floor() + 1).clamp(1, totalLaps + 1).toInt();
    if (newLap > prevLap) {
      final double lapDuration = totalRaceTime - lapStartTime;
      lapStartTime = totalRaceTime;
      if (lapDuration < bestLapTime) bestLapTime = lapDuration;
      if (lapDuration < fastLapTime) fastLapTime = lapDuration;

      if (newLap > totalLaps) {
        raceFinished = true;
        F1SoundEngine.stop();
        F1SoundEngine.playEvent('finish');
        notifyListeners();
        return 2;
      } else {
        F1SoundEngine.playEvent('lap');
      }
    }

    notifyListeners();
    return 0;
  }

  void _updateSmartAiAndCollisions(double dt) {
    rivalCloseLeft = false;
    rivalCloseRight = false;

    // PHASE A: Individual Pro AI Racecraft (Anti-Wall Radar, Single-File Corner Discipline & Clean 2-Wide Overtakes)
    for (int i = 0; i < aiDrivers.length; i++) {
      final AiDriver ai = aiDrivers[i];
      ai.prevTrackDist = ai.trackDist;

      if (ai.overtakeCommitTimer > 0) ai.overtakeCommitTimer = max(0.0, ai.overtakeCommitTimer - dt);
      if (ai.defenseCooldown > 0) ai.defenseCooldown = max(0.0, ai.defenseCooldown - dt);
      if (ai.collisionCooldown > 0) ai.collisionCooldown = max(0.0, ai.collisionCooldown - dt);

      // Realistic F1 standing-start reaction delay
      if (totalRaceTime < ai.launchDelay) {
        ai.currentSpeedKmh = 0.0;
        continue;
      }

      // 1. Pro-level lookahead curvature analysis
      final double kNowSigned = _curvatureAtDist(ai.trackDist);
      final double kNearSigned = _curvatureAtDist(ai.trackDist + 50.0);
      final double kNow = kNowSigned.abs();
      final double kNear = kNearSigned.abs();
      final double kBrakeZone = _curvatureAtDist(ai.trackDist + 105.0).abs();
      final double maxUpcomingK = max(kNow, max(kNear * 0.90, kBrakeZone * 0.72));

      final double cornerGripFactor = (1.0 - (maxUpcomingK * (0.145 - ai.skill * 0.048))).clamp(0.58, 1.0).toDouble();
      double desiredSpeed = ai.baseMaxSpeedKmh * cornerGripFactor;

      // 2. Wide-range traffic & anti-wall cluster radar
      double closestAheadDz = 999.0;
      double closestAheadLane = 0.0;
      double closestAheadSpeed = 999.0;
      bool sideBlockedLeft = false;
      bool sideBlockedRight = false;
      int abreastCount = 0;
      int aheadClusterCount = 0;

      for (int j = 0; j < aiDrivers.length; j++) {
        if (i == j) continue;
        final AiDriver other = aiDrivers[j];
        final double dz = other.trackDist - ai.trackDist;
        final double dx = other.laneX - ai.laneX;
        if (dz > 2.5 && dz < 64.0 && dx.abs() < 0.65 && dz < closestAheadDz) {
          closestAheadDz = dz;
          closestAheadLane = other.laneX;
          closestAheadSpeed = other.currentSpeedKmh;
        }
        if (dz.abs() < 10.5) {
          abreastCount++;
          if (dx < 0 && dx > -0.68) sideBlockedLeft = true;
          if (dx > 0 && dx < 0.68) sideBlockedRight = true;
        }
        if (dz > 4.0 && dz < 24.0) {
          aheadClusterCount++;
        }
      }

      final double dzPlayer = playerDist - ai.trackDist;
      final double dxPlayer = carX - ai.laneX;
      if (dzPlayer > 2.5 && dzPlayer < 64.0 && dxPlayer.abs() < 0.65 && dzPlayer < closestAheadDz) {
        closestAheadDz = dzPlayer;
        closestAheadLane = carX;
        closestAheadSpeed = speedKmh;
      }
      if (dzPlayer.abs() < 10.5) {
        if (dxPlayer < 0 && dxPlayer > -0.66) sideBlockedLeft = true;
        if (dxPlayer > 0 && dxPlayer < 0.66) sideBlockedRight = true;
      }

      // 3. Proactive Slipstream, Corner-Exit Boost & Tactical DRS/ERS
      final bool directlyBehind = closestAheadDz < 48.0 && closestAheadDz > 6.0 && (closestAheadLane - ai.laneX).abs() < 0.42;
      ai.isDrafting = directlyBehind && kNow < 0.55;
      final bool onStraight = kNow < 0.42 && kNear < 0.55;
      final bool inCorner = kNow > 0.55 || kNear > 0.75;
      final bool cornerExitBoost = kNow < 0.35 && ai.currentSpeedKmh < 248.0 && ai.ersCharge > 22.0;
      final double playerBehindDz = ai.trackDist - playerDist;
      final bool defendingPlayer = playerBehindDz > 5.0 && playerBehindDz < 32.0 && speedKmh > ai.currentSpeedKmh + 4.0 && abreastCount == 0;
      final bool wantsOvertake = ai.isDrafting && (ai.baseMaxSpeedKmh > closestAheadSpeed - 8.0) && abreastCount == 0 && aheadClusterCount <= 1;

      if ((wantsOvertake || defendingPlayer || cornerExitBoost || (ai.ersCharge > 40.0 && onStraight && abreastCount == 0 && dzPlayer.abs() < 80.0)) &&
          onStraight &&
          ai.ersCharge > 6.0) {
        ai.drsOpen = true;
        ai.ersCharge = max(0.0, ai.ersCharge - 16.5 * dt);
        desiredSpeed += 22.0 + (ai.isDrafting ? 16.0 : 0.0);
      } else {
        ai.drsOpen = false;
        ai.ersCharge = min(100.0, ai.ersCharge + (ai.isBraking ? 30.0 : 9.0) * dt);
        if (ai.isDrafting) desiredSpeed += 12.0;
      }

      // Mild pack cohesion without bunching cars into walls
      final double deltaToPlayer = playerDist - ai.trackDist;
      if (deltaToPlayer > 280.0) desiredSpeed += 11.0;
      if (deltaToPlayer < -440.0) desiredSpeed -= 6.0;

      // 4. Pro F1 Racing Line + Anti-Wall Overtake Discipline + Smart Defense
      double targetX = _idealRacingLineX(ai.trackDist);

      // 4A. Slipstream Hunting on straights
      if (onStraight && closestAheadDz >= 24.0 && closestAheadDz < 54.0 && ai.overtakeCommitTimer <= 0 && abreastCount == 0) {
        targetX = closestAheadLane.clamp(-0.78, 0.78).toDouble();
      }

      // 4B. Clean Overtaking (NEVER initiates 3-wide walls; keeps 2-wide compact on one side of track!)
      final bool canStartOvertake = (!inCorner) && abreastCount == 0 && aheadClusterCount <= 1;
      if (closestAheadDz < 32.0 && (ai.currentSpeedKmh > closestAheadSpeed - 6.0 || ai.drsOpen)) {
        if (canStartOvertake) {
          if (ai.overtakeCommitTimer <= 0) {
            final bool cornerAhead = kNear > 0.65;
            final bool diveLeft = cornerAhead && kNearSigned < 0 && ai.aggression > 0.80;
            final bool diveRight = cornerAhead && kNearSigned > 0 && ai.aggression > 0.80;

            if (diveLeft && !sideBlockedLeft) {
              ai.overtakeSide = -1.0;
            } else if (diveRight && !sideBlockedRight) {
              ai.overtakeSide = 1.0;
            } else if (closestAheadLane <= -0.15 && !sideBlockedRight) {
              // Keep both cars on the same side of center so the opposite corridor stays wide open!
              ai.overtakeSide = 1.0;
            } else if (closestAheadLane >= 0.15 && !sideBlockedLeft) {
              ai.overtakeSide = -1.0;
            } else if (!sideBlockedLeft) {
              ai.overtakeSide = -1.0;
            } else if (!sideBlockedRight) {
              ai.overtakeSide = 1.0;
            } else {
              ai.overtakeSide = 0.0;
            }
            ai.overtakeCommitTimer = 1.15 + (ai.aggression * 0.45);
          }
          if (ai.overtakeSide != 0.0) {
            targetX = (closestAheadLane + ai.overtakeSide * 0.48).clamp(-0.80, 0.80).toDouble();
          }
        } else {
          // Traffic cluster or corner ahead: stay in single file behind instead of creating a wall!
          ai.overtakeSide = 0.0;
          ai.overtakeCommitTimer = 0.0;
          targetX = closestAheadLane.clamp(-0.80, 0.80).toDouble();
          if (closestAheadDz < 14.0) {
            desiredSpeed = min(desiredSpeed, closestAheadSpeed - (14.0 - closestAheadDz) * 1.6);
          }
        }
      } else if (ai.overtakeCommitTimer > 0 && ai.overtakeSide != 0.0 && abreastCount <= 1) {
        targetX = (ai.laneX + ai.overtakeSide * 0.10).clamp(-0.80, 0.80).toDouble();
      } else {
        ai.overtakeSide = 0.0;
      }

      // 4C. Clean Early Defense ONLY when player is far enough (>20m) and never chopping into player's lane
      if (playerBehindDz > 20.0 && playerBehindDz < 40.0 && speedKmh > ai.currentSpeedKmh + 6.0 && abreastCount == 0 && ai.defenseCooldown <= 0) {
        if (rng.nextDouble() < ai.defenseSkill * 0.14) {
          final double nextK = _curvatureAtDist(ai.trackDist + 85.0);
          final double insideLine = nextK.abs() > 0.28 ? (nextK.sign * 0.56) : (carX >= 0 ? -0.45 : 0.45);
          if ((insideLine - carX).abs() > 0.48 &&
              ((insideLine < ai.laneX && !sideBlockedLeft) || (insideLine > ai.laneX && !sideBlockedRight))) {
            targetX = insideLine;
            ai.defenseCooldown = 2.6;
          }
        }
      }

      // 4D. ACTIVE PLAYER EVASION & COLLISION-AVOIDANCE SYSTEM
      // Bots actively dodge around the player, brake early behind you, and yield room wheel-to-wheel!
      bool evadingPlayer = false;
      final double absDxPlayer = dxPlayer.abs();

      // Case 1: AI is BEHIND the player and closing in (prevent rear-ending or cutting across)
      if (dzPlayer > 1.5 && dzPlayer < 40.0) {
        final double closingMs = (ai.currentSpeedKmh - speedKmh) / 3.6;
        final double ttc = closingMs > 0.5 ? (dzPlayer / closingMs) : 99.0;
        if (absDxPlayer < 0.68) {
          evadingPlayer = true;
          // Pick the safest open side away from the player (prefer away from track edges)
          double evadeDir;
          if (carX > 0.22 && !sideBlockedLeft) {
            evadeDir = -1.0;
          } else if (carX < -0.22 && !sideBlockedRight) {
            evadeDir = 1.0;
          } else if (ai.laneX >= carX && !sideBlockedRight) {
            evadeDir = 1.0;
          } else if (!sideBlockedLeft) {
            evadeDir = -1.0;
          } else {
            evadeDir = (ai.laneX >= carX) ? 1.0 : -1.0;
          }
          targetX = (carX + evadeDir * 0.72).clamp(-0.90, 0.90).toDouble();

          // Emergency braking if still lined up closely behind the player (e.g. player braked hard!)
          if ((dzPlayer < 20.0 || ttc < 1.35) && absDxPlayer < 0.56) {
            final double safeCap = max(0.0, speedKmh - (22.0 - min(20.0, dzPlayer)) * 1.8);
            desiredSpeed = min(desiredSpeed, safeCap);
            ai.drsOpen = false;
          }
        }
      }
      // Case 2: Wheel-to-wheel alongside the player -> actively give wide racing room!
      else if (dzPlayer.abs() <= 13.0) {
        if (absDxPlayer < 0.72) {
          evadingPlayer = true;
          final double awayDir = (ai.laneX >= carX) ? 1.0 : -1.0;
          final double safeLane = (carX + awayDir * 0.74).clamp(-0.92, 0.92).toDouble();
          targetX = safeLane;
        }
      }
      // Case 3: AI is AHEAD of the player and player is closing very fast directly behind -> move gently aside to avoid contact!
      else if (playerBehindDz > 3.0 && playerBehindDz < 24.0 && speedKmh > ai.currentSpeedKmh + 16.0) {
        if (absDxPlayer < 0.54) {
          evadingPlayer = true;
          final double dodgeDir = (ai.laneX >= carX)
              ? (!sideBlockedRight ? 1.0 : -1.0)
              : (!sideBlockedLeft ? -1.0 : 1.0);
          targetX = (carX + dodgeDir * 0.66).clamp(-0.88, 0.88).toDouble();
        }
      }

      if (!evadingPlayer) {
        if (sideBlockedLeft && targetX < ai.laneX) targetX = max(targetX, ai.laneX + 0.03);
        if (sideBlockedRight && targetX > ai.laneX) targetX = min(targetX, ai.laneX - 0.03);
      }
      targetX = targetX.clamp(-0.92, 0.92).toDouble();

      // 5. Crisp F1 Acceleration & High-Responsiveness Evasive Braking
      final double speedDiff = desiredSpeed - ai.currentSpeedKmh;
      if (speedDiff > 0) {
        final double launchBoost = ai.currentSpeedKmh < 140.0 ? (18.0 + ai.skill * 18.0) : 0.0;
        final double aiAccel = (142.0 + ai.skill * 34.0) + (ai.drsOpen ? 42.0 : 0.0) + launchBoost;
        ai.currentSpeedKmh = min(desiredSpeed, ai.currentSpeedKmh + aiAccel * dt);
        ai.isBraking = false;
      } else {
        final double aiBrake = (evadingPlayer ? 360.0 : 268.0) + ai.skill * 65.0;
        ai.currentSpeedKmh = max(desiredSpeed, ai.currentSpeedKmh - aiBrake * dt);
        ai.isBraking = speedDiff < -12.0;
      }

      ai.trackDist += (ai.currentSpeedKmh / 3.6) * dt;
      ai.lateralVel *= exp(-6.0 * dt);
      final double prevLane = ai.laneX;
      final double laneResponse = (evadingPlayer ? 7.2 : 3.6) + ai.skill * 1.6;
      ai.laneX += ((targetX - ai.laneX) * laneResponse + ai.lateralVel) * dt;
      ai.laneX = ai.laneX.clamp(-0.94, 0.94).toDouble();

      final double actualLatRate = (ai.laneX - prevLane) / max(dt, 0.004);
      final double targetTilt = (actualLatRate * 0.08).clamp(-0.14, 0.14).toDouble();
      ai.steerTilt += (targetTilt - ai.steerTilt) * (1.0 - exp(-10.0 * dt));
    }

    // PHASE B: Anti-Wall Longitudinal & Corridor Enforcement (Front-to-Back)
    // Guarantees zero 3-wide walls, resolves side-by-side deadlocks fast, and ALWAYS leaves a clean passing lane!
    final List<int> order = List<int>.generate(aiDrivers.length, (i) => i);
    order.sort((a, b) => aiDrivers[b].trackDist.compareTo(aiDrivers[a].trackDist));

    for (int rank = 1; rank < order.length; rank++) {
      final AiDriver lead = aiDrivers[order[rank - 1]];
      final AiDriver trail = aiDrivers[order[rank]];
      final double dz = lead.trackDist - trail.trackDist;
      final double dx = (lead.laneX - trail.laneX).abs();

      if (dz < 9.5) {
        // Never allow 3 cars within 15m to fan out across the track: tuck the 3rd car cleanly behind!
        if (rank >= 2 && (aiDrivers[order[rank - 2]].trackDist - trail.trackDist) < 15.0) {
          trail.currentSpeedKmh = min(trail.currentSpeedKmh, max(50.0, lead.currentSpeedKmh - 14.0));
          trail.trackDist = min(trail.trackDist, lead.trackDist - 7.8);
          trail.overtakeSide = 0.0;
          trail.overtakeCommitTimer = 0.0;
          trail.laneX += (lead.laneX - trail.laneX) * min(1.0, 6.0 * dt);
        } else if (dx >= 0.44) {
          // Two cars temporarily side-by-side: resolve quickly so they don't form a moving barrier
          if (trail.currentSpeedKmh <= lead.currentSpeedKmh + 6.0) {
            trail.currentSpeedKmh = max(55.0, trail.currentSpeedKmh - 16.0 * dt);
          } else {
            lead.currentSpeedKmh = max(55.0, lead.currentSpeedKmh - 10.0 * dt);
          }
          // If the pair straddles center (e.g. -0.45 and +0.45), bias the pair toward one side so the opposite lane is open!
          if (lead.laneX * trail.laneX < 0 && dx > 0.56) {
            final double bias = (lead.laneX + trail.laneX) <= 0 ? -1.0 : 1.0;
            lead.laneX = (lead.laneX + bias * 0.9 * dt).clamp(-0.84, 0.84).toDouble();
            trail.laneX = (trail.laneX + bias * 0.9 * dt).clamp(-0.84, 0.84).toDouble();
          }
        } else if (dz < 6.8) {
          // Same lane and too close: resolve longitudinally (lift/brake behind) instead of shoving sideways into a wall!
          trail.trackDist = min(trail.trackDist, lead.trackDist - 6.8);
          trail.currentSpeedKmh = min(trail.currentSpeedKmh, lead.currentSpeedKmh - 4.0);
        }
      }
    }

    // PHASE C: Mirror Radar & Precision Swept Player-vs-AI Collision Detection
    for (int i = 0; i < aiDrivers.length; i++) {
      final AiDriver ai = aiDrivers[i];

      final double behindDist = playerDist - ai.trackDist;
      if (behindDist > 2.4 && behindDist < 32.0) {
        if (ai.laneX <= carX) {
          rivalCloseLeft = true;
        } else {
          rivalCloseRight = true;
        }
      }

      final double prevDz = ai.prevTrackDist - prevPlayerDist;
      final double currDz = ai.trackDist - playerDist;
      final double minDz = min(prevDz, currDz);
      final double maxDz = max(prevDz, currDz);
      final bool zOverlaps = (maxDz >= kCarLengthOverlapBack) && (minDz <= kCarLengthOverlapFront);
      final double dxSigned = carX - ai.laneX;
      final double absDx = dxSigned.abs();

      if (zOverlaps && absDx < kCarCollisionDxLane && ai.collisionCooldown <= 0.0) {
        final bool isRearEndByPlayer = (currDz > 1.7) && (absDx < kCarCollisionDxLane * 0.72) && (speedKmh > ai.currentSpeedKmh + 8.0);
        final bool isRearEndedByAi = (currDz < -1.4) && (absDx < kCarCollisionDxLane * 0.72) && (ai.currentSpeedKmh > speedKmh + 10.0);

        if (isRearEndByPlayer) {
          final double closingKmh = (speedKmh - ai.currentSpeedKmh).clamp(10.0, 140.0).toDouble();
          final double severity = (closingKmh / 80.0).clamp(0.45, 1.5).toDouble();
          final double deflectDir = dxSigned >= 0 ? 1.0 : -1.0;

          playerDist = ai.trackDist - kCarLengthOverlapFront - 0.15;
          speedKmh = max(0.0, min(speedKmh, ai.currentSpeedKmh - closingKmh * 0.35));
          ai.currentSpeedKmh = min(345.0, ai.currentSpeedKmh + closingKmh * 0.18);

          lateralVel += deflectDir * (1.85 * severity);
          spinYaw = deflectDir * (0.24 * severity);
          controlRecoveryTimer = 0.45 * severity;
          hitFlash = (0.55 + 0.45 * severity).clamp(0.55, 1.0).toDouble();
          ersToggledOn = false;
          ai.collisionCooldown = 0.42;

          spawnParticles(const Color(0xFFFFD54F), 14, sparks: true);
          F1SoundEngine.playEvent('crash', intensity: (0.6 + 0.4 * severity).clamp(0.6, 1.0).toDouble());
          showRadio('¡IMPACTO TRASERO CON ${ai.code}!', secs: 1.8);
        } else if (isRearEndedByAi) {
          final double closingKmh = (ai.currentSpeedKmh - speedKmh).clamp(10.0, 110.0).toDouble();
          ai.trackDist = playerDist + kCarLengthOverlapBack - 0.15;
          ai.currentSpeedKmh = max(45.0, speedKmh - 12.0);
          speedKmh = min(355.0, speedKmh + closingKmh * 0.20);
          final double pushDir = dxSigned >= 0 ? 1.0 : -1.0;
          lateralVel += pushDir * 0.95;
          hitFlash = 0.55;
          ai.collisionCooldown = 0.45;
          spawnParticles(const Color(0xFFFFAB00), 8, sparks: true);
          F1SoundEngine.playEvent('crash', intensity: 0.65);
        } else {
          final double pushDir = dxSigned >= 0 ? 1.0 : -1.0;
          final double penetration = (kCarCollisionDxLane - absDx).clamp(0.02, kCarCollisionDxLane).toDouble();
          carX += pushDir * (penetration * 0.68 + 0.03);
          ai.laneX -= pushDir * (penetration * 0.32 + 0.02);

          final double speedFactor = (speedKmh / 210.0).clamp(0.55, 1.65).toDouble();
          final double hardHit = (penetration / 0.18).clamp(0.65, 1.45).toDouble();

          lateralVel = pushDir * (2.45 * speedFactor * hardHit);
          spinYaw = pushDir * (0.30 * hardHit);
          controlRecoveryTimer = 0.25;
          speedKmh = max(0.0, speedKmh * (1.0 - 0.18 * hardHit));
          hitFlash = (0.65 + 0.35 * hardHit).clamp(0.65, 1.0).toDouble();
          ersToggledOn = false;

          ai.lateralVel = -pushDir * (1.75 * hardHit);
          ai.currentSpeedKmh = max(60.0, ai.currentSpeedKmh * 0.88);
          ai.collisionCooldown = 0.42;

          spawnParticles(const Color(0xFFFFD54F), 14, sparks: true);
          F1SoundEngine.playEvent('crash', intensity: (0.55 + 0.45 * hardHit).clamp(0.55, 1.0).toDouble());
          showRadio('¡TOQUE RUEDA A RUEDA CON ${ai.code}!', secs: 1.9);
        }
      }
    }
  }
}

class CockpitRaceScreen extends StatefulWidget {
  final CircuitInfo circuit;
  final TeamLivery livery;

  const CockpitRaceScreen({
    super.key,
    required this.circuit,
    required this.livery,
  });

  @override
  State<CockpitRaceScreen> createState() => _CockpitRaceScreenState();
}

class _CockpitRaceScreenState extends State<CockpitRaceScreen> with SingleTickerProviderStateMixin, WidgetsBindingObserver {
  late final RaceEngineState engine;
  late final Ticker _ticker;
  final ValueNotifier<int> _hudTick = ValueNotifier<int>(0);
  Duration _lastElapsed = Duration.zero;
  double _hudAccumulator = 0.0;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    SystemChrome.setPreferredOrientations([
      DeviceOrientation.landscapeLeft,
      DeviceOrientation.landscapeRight,
    ]);
    engine = RaceEngineState(circuit: widget.circuit, livery: widget.livery);
    _ticker = createTicker(_onTick)..start();
  }

  void _onTick(Duration elapsed) {
    final double rawDt = (elapsed - _lastElapsed).inMicroseconds / 1000000.0;
    _lastElapsed = elapsed;
    if (rawDt <= 0.0) return;
    final double dt = rawDt.clamp(0.001, 0.036).toDouble();

    final int status = engine.step(dt);
    if (status == 1) {
      // Qualifying finished -> show Starting Grid overlay immediately!
      _hudTick.value++;
      return;
    } else if (status == 2) {
      _ticker.stop();
      _hudTick.value++;
      _showFinishDialog();
      return;
    }

    _hudAccumulator += dt;
    if (_hudAccumulator >= 0.06) {
      _hudAccumulator = 0.0;
      _hudTick.value++;
    }
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if ((state == AppLifecycleState.paused || state == AppLifecycleState.inactive) &&
        !engine.isPaused &&
        !engine.raceFinished &&
        engine.phase != SessionPhase.gridOverview) {
      engine.togglePause();
      _hudTick.value++;
    }
  }

  @override
  void dispose() {
    F1SoundEngine.stop();
    WidgetsBinding.instance.removeObserver(this);
    _ticker.dispose();
    engine.dispose();
    _hudTick.dispose();
    SystemChrome.setPreferredOrientations([
      DeviceOrientation.portraitUp,
      DeviceOrientation.landscapeLeft,
      DeviceOrientation.landscapeRight,
    ]);
    super.dispose();
  }

  String _formatTime(double seconds) {
    if (seconds >= 900) return '--:--.---';
    final int mins = seconds ~/ 60;
    final int secs = seconds.toInt() % 60;
    final int ms = ((seconds - seconds.floor()) * 1000).toInt();
    return '${mins.toString().padLeft(2, '0')}:${secs.toString().padLeft(2, '0')}.${ms.toString().padLeft(3, '0')}';
  }

  int _pointsForPos(int pos) {
    const List<int> table = [25, 18, 15, 12, 10, 8, 6, 4, 2, 1];
    return pos <= 10 ? table[pos - 1] : 0;
  }

  void _toggleErs() {
    if (engine.isPaused || engine.startLightsTimer > 0 || engine.phase == SessionPhase.gridOverview) return;
    if (!engine.ersToggledOn && engine.ersCharge < 5.0) {
      engine.showRadio('BATERÍA ERS BAJA — FRENA PARA RECARGAR', secs: 2.0);
      _hudTick.value++;
      return;
    }
    engine.ersToggledOn = !engine.ersToggledOn;
    if (engine.ersToggledOn) {
      F1SoundEngine.playEvent('ers');
    }
    _hudTick.value++;
  }

  void _showFinishDialog() {
    final int pos = engine.currentPosition;
    final int pts = _pointsForPos(pos);
    showDialog<void>(
      context: context,
      barrierDismissible: false,
      builder: (ctx) {
        return AlertDialog(
          backgroundColor: const Color(0xFF0E1420),
          shape: RoundedRectangleBorder(
            borderRadius: BorderRadius.circular(16),
            side: BorderSide(color: pos <= 3 ? const Color(0xFFFFD54F) : const Color(0xFFE10600), width: 2),
          ),
          title: Text(
            'BANDERA A CUADROS — ${widget.circuit.gpName}',
            style: const TextStyle(fontSize: 15, fontWeight: FontWeight.w900),
            textAlign: TextAlign.center,
          ),
          content: Column(
            mainAxisSize: MainAxisSize.min,
            children: [
              Text(
                'POSICIÓN P$pos / ${RaceEngineState.totalCars}',
                style: TextStyle(
                  fontSize: 26,
                  fontWeight: FontWeight.w900,
                  color: pos == 1 ? const Color(0xFFFFD54F) : Colors.white,
                ),
              ),
              const SizedBox(height: 6),
              Text('Salida desde: P${engine.playerGridPosition}', style: const TextStyle(fontSize: 12, color: Colors.white70)),
              const SizedBox(height: 6),
              Text('Puntos obtenidos: +$pts PTS', style: const TextStyle(color: Color(0xFF00E676), fontWeight: FontWeight.bold)),
              const SizedBox(height: 4),
              Text('Mejor vuelta: ${_formatTime(engine.bestLapTime)}', style: const TextStyle(color: Colors.white70)),
              Text('Tiempo total: ${_formatTime(engine.totalRaceTime)}', style: const TextStyle(color: Colors.white70)),
            ],
          ),
          actions: [
            TextButton(
              onPressed: () {
                Navigator.pop(ctx);
                Navigator.pop(context, RaceFinishData(position: pos, points: pts, nextRound: false));
              },
              child: const Text('CALENDARIO'),
            ),
            if (widget.circuit.round < 24)
              ElevatedButton(
                style: ElevatedButton.styleFrom(backgroundColor: const Color(0xFFE10600), foregroundColor: Colors.white),
                onPressed: () {
                  Navigator.pop(ctx);
                  Navigator.pop(context, RaceFinishData(position: pos, points: pts, nextRound: true));
                },
                child: const Text('SIGUIENTE GP >'),
              ),
          ],
        );
      },
    );
  }

  List<Map<String, Object>> _getMiniLeaderboard() {
    final List<Map<String, Object>> entries = [
      {'code': 'YOU', 'dist': engine.playerDist, 'color': widget.livery.primary, 'isPlayer': true},
      ...engine.aiDrivers.map((a) => {'code': a.code, 'dist': a.trackDist, 'color': a.bodyColor, 'isPlayer': false}),
    ];
    entries.sort((a, b) => (b['dist'] as double).compareTo(a['dist'] as double));

    final int pIdx = entries.indexWhere((e) => e['isPlayer'] == true);
    final int start = max(0, min(entries.length - 3, pIdx - 1));
    final List<Map<String, Object>> slice = [];
    for (int i = start; i < min(entries.length, start + 3); i++) {
      final double gapMeters = (entries[start]['dist'] as double) - (entries[i]['dist'] as double);
      final double gapSec = gapMeters / 65.0;
      slice.add({
        'pos': i + 1,
        'code': entries[i]['code'] as String,
        'color': entries[i]['color'] as Color,
        'isPlayer': entries[i]['isPlayer'] as bool,
        'gap': i == start ? 'GAP' : '+${gapSec.toStringAsFixed(3)}',
      });
    }
    return slice;
  }

