class RealCircuitMinimapPainter extends CustomPainter {
  final TrackGeometry geometry;
  final double playerProgress;
  final List<double> aiProgresses;
  final Color kerbColor;

  RealCircuitMinimapPainter({
    required this.geometry,
    required this.playerProgress,
    required this.aiProgresses,
    required this.kerbColor,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final double cx = size.width * 0.5;
    final double cy = size.height * 0.5;
    final double r = min(size.width, size.height) * 0.46;

    final Path path = Path();
    for (int i = 0; i < geometry.smoothPoints.length; i++) {
      final Offset p = geometry.smoothPoints[i];
      final double x = cx + p.dx * r;
      final double y = cy + p.dy * r;
      if (i == 0) {
        path.moveTo(x, y);
      } else {
        path.lineTo(x, y);
      }
    }
    path.close();

    canvas.drawPath(
      path,
      Paint()
        ..isAntiAlias = true
        ..color = Colors.white70
        ..style = PaintingStyle.stroke
        ..strokeWidth = 2.6
        ..strokeJoin = StrokeJoin.round,
    );

    final Offset sf = geometry.pointAtProgress(0.0);
    canvas.drawCircle(Offset(cx + sf.dx * r, cy + sf.dy * r), 3.0, Paint()..isAntiAlias = true..color = kerbColor);

    final Paint aiPaint = Paint()..isAntiAlias = true..color = const Color(0xAAFF5252);
    for (final prog in aiProgresses) {
      final Offset ap = geometry.pointAtProgress(prog);
      canvas.drawCircle(Offset(cx + ap.dx * r, cy + ap.dy * r), 1.8, aiPaint);
    }

    final Offset pp = geometry.pointAtProgress(playerProgress);
    canvas.drawCircle(Offset(cx + pp.dx * r, cy + pp.dy * r), 3.9, Paint()..isAntiAlias = true..color = const Color(0xFF00E676));
  }

  @override
  bool shouldRepaint(covariant CustomPainter oldDelegate) => true;
}

class F1UltraSmoothPainter extends CustomPainter {
  final RaceEngineState engine;

  static const int segCount = 128;
  final List<double> _segZ = List<double>.filled(segCount + 2, 0.0);
  final List<double> _segShift = List<double>.filled(segCount + 2, 0.0);
  final List<double> _segElev = List<double>.filled(segCount + 2, 0.0);
  final List<AiDriver> _visibleRivals = [];

  final Paint _fillPaint = Paint()..isAntiAlias = true;
  final Paint _strokePaint = Paint()..isAntiAlias = true..style = PaintingStyle.stroke;
  final Path _quadPath = Path();
  final Path _asphaltClipPath = Path();
  final Path _backRangePath = Path();
  final Path _frontRangePath = Path();

  Size _cachedSize = Size.zero;
  Paint? _vignettePaint;
  final Map<String, TextPainter> _tagCache = {};

  F1UltraSmoothPainter({required this.engine}) : super(repaint: engine);

  TextPainter _getCachedTag(String code) {
    return _tagCache.putIfAbsent(code, () {
      return TextPainter(
        text: TextSpan(
          text: code,
          style: const TextStyle(color: Colors.white, fontSize: 11.0, fontWeight: FontWeight.w900, letterSpacing: 0.5),
        ),
        textDirection: TextDirection.ltr,
      )..layout();
    });
  }

  double _curveAtWorldDist(double dist) {
    final double prog = (dist % engine.circuit.lapLengthMeters) / engine.circuit.lapLengthMeters;
    return engine.geometry.curvatureAtProgress(prog);
  }

  double _hillAtWorldDist(double dist) {
    final double prog = (dist % engine.circuit.lapLengthMeters) / engine.circuit.lapLengthMeters;
    return sin(prog * pi * 4.0 + engine.circuit.round) * engine.circuit.hillAmp;
  }

  Offset _project(double x, double y, double z, double w, double horizonY, double fovMult) {
    final double fov = w * fovMult;
    final double scale = fov / max(z, 0.18);
    return Offset(w * 0.5 + x * scale, horizonY - y * scale);
  }

  @override
  void paint(Canvas canvas, Size size) {
    final CircuitInfo circuit = engine.circuit;
    final double w = size.width;
    final double h = size.height;
    final bool cockpit = engine.cockpitCamera;

    if (size != _cachedSize) {
      _cachedSize = size;
      _vignettePaint = Paint()
        ..shader = const RadialGradient(
          radius: 1.06,
          stops: [0.66, 1.0],
          colors: [Color(0x00000000), Color(0x52000000)],
        ).createShader(Rect.fromLTWH(0, 0, w, h));
    }

    final double pitchOffset = engine.smoothPitch * (cockpit ? 7.5 : 4.5);
    final double horizonY = (cockpit ? h * 0.452 : h * 0.422) + pitchOffset;
    final double fovMult = 0.60 - (engine.smoothFovBoost * 0.055);

    canvas.save();
    final double totalRoll = engine.smoothCamBank + engine.spinYaw * 0.22;
    if (totalRoll.abs() > 0.001) {
      canvas.translate(w * 0.5, h * 0.5);
      canvas.rotate(totalRoll);
      canvas.translate(-w * 0.5, -h * 0.5);
    }

    // 1. Environment
    _drawProEnvironment(canvas, w, h, horizonY, circuit);

    // 2. Ground
    final Rect groundRect = Rect.fromLTWH(0, horizonY, w, h - horizonY + 40);
    canvas.drawRect(
      groundRect,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [
            Color.lerp(circuit.groundColor, circuit.skyBottom, 0.42)!,
            circuit.groundColor,
            Color.lerp(circuit.groundColor, Colors.black, 0.36)!,
          ],
        ).createShader(groundRect),
    );
    if (UltraTextures.turfGrainShader != null) {
      canvas.save();
      final double scrollG = (engine.playerDist * 10.0) % 128.0;
      canvas.translate(0, scrollG);
      canvas.drawRect(
        Rect.fromLTWH(0, horizonY - 128, w, h - horizonY + 256),
        Paint()..shader = UltraTextures.turfGrainShader..filterQuality = FilterQuality.medium,
      );
      canvas.restore();
    }

    // 3. 128-Slice 3D Track
    const double roadHalfW = 3.20;
    const double kerbOuterW = 3.64;
    const double astroOuterW = 4.06;
    const double runoffHalfW = 5.38;
    const double baseSegLen = 0.68;
    final double zOffset = engine.playerDist % baseSegLen;
    final double baseCamHeight = cockpit ? -1.16 : -1.86;
    final double playerHill = _hillAtWorldDist(engine.playerDist);

    double dxAcc = 0.0;
    double xAcc = 0.0;
    for (int i = 1; i <= segCount + 1; i++) {
      final double zVal = (i * baseSegLen) + (i * i * 0.0020) - zOffset;
      _segZ[i] = zVal;
      final double wd = engine.playerDist + zVal * 2.0;
      final double k = _curveAtWorldDist(wd);
      dxAcc += k * 0.0063;
      xAcc += dxAcc;
      _segShift[i] = xAcc;
      _segElev[i] = (_hillAtWorldDist(wd) - playerHill) * (i / segCount);
    }

    final double camShift = engine.carX * RaceEngineState.kLaneToWorldX + engine.spinYaw * 1.4;
    _asphaltClipPath.reset();

    for (int i = segCount; i >= 1; i--) {
      final double z1 = _segZ[i];
      final double z2 = _segZ[i + 1];
      if (z1 <= 0.26) continue;

      final double worldDist1 = engine.playerDist + z1 * 2.0;
      final double lapDist1 = worldDist1 % circuit.lapLengthMeters;
      final int segIndex = (worldDist1 / 1.75).floor();

      final double s1 = _segShift[i] - camShift;
      final double s2 = _segShift[i + 1] - camShift;
      final double y1 = baseCamHeight + _segElev[i];
      final double y2 = baseCamHeight + _segElev[i + 1];

      final double depthT = (i / segCount).clamp(0.0, 1.0).toDouble();
      final double fogMix = pow(depthT, 2.2).toDouble() * 0.80;

      final Offset r1L = _project(-runoffHalfW + s1, y1, z1, w, horizonY, fovMult);
      final Offset r1R = _project(runoffHalfW + s1, y1, z1, w, horizonY, fovMult);
      final Offset r2L = _project(-runoffHalfW + s2, y2, z2, w, horizonY, fovMult);
      final Offset r2R = _project(runoffHalfW + s2, y2, z2, w, horizonY, fovMult);

      final Color runoffCol = Color.lerp(
        segIndex % 2 == 0 ? circuit.runoffColor : Color.lerp(circuit.runoffColor, Colors.black, 0.08)!,
        circuit.skyBottom,
        fogMix,
      )!;
      _drawQuad(canvas, r1L, r1R, r2R, r2L, runoffCol);

      const double wallH = 0.78;
      final Offset w1LT = _project(-runoffHalfW + s1, y1 + wallH, z1, w, horizonY, fovMult);
      final Offset w2LT = _project(-runoffHalfW + s2, y2 + wallH, z2, w, horizonY, fovMult);
      final Offset w1RT = _project(runoffHalfW + s1, y1 + wallH, z1, w, horizonY, fovMult);
      final Offset w2RT = _project(runoffHalfW + s2, y2 + wallH, z2, w, horizonY, fovMult);

      final Color wallBase = (segIndex % 10 < 5)
          ? const Color(0xFF161D28)
          : (segIndex % 20 < 10 ? circuit.kerbA : const Color(0xFFEBEFF5));
      final Color wallCol = Color.lerp(wallBase, circuit.skyBottom, fogMix)!;
      _drawQuad(canvas, r1L, w1LT, w2LT, r2L, wallCol);
      _drawQuad(canvas, r1R, r2R, w2RT, w1RT, wallCol);

      if (i % 6 == 0 && i < segCount - 16) {
        final Offset fLT = _project(-runoffHalfW + s1, y1 + 1.94, z1, w, horizonY, fovMult);
        final Offset fRT = _project(runoffHalfW + s1, y1 + 1.94, z1, w, horizonY, fovMult);
        _strokePaint
          ..color = Color.lerp(const Color(0x6AB0BEC5), circuit.skyBottom, fogMix)!
          ..strokeWidth = max(1.0, 4.2 / z1);
        canvas.drawLine(w1LT, fLT, _strokePaint);
        canvas.drawLine(w1RT, fRT, _strokePaint);
      }

      final Offset a1LO = _project(-astroOuterW + s1, y1 + 0.02, z1, w, horizonY, fovMult);
      final Offset a2LO = _project(-astroOuterW + s2, y2 + 0.02, z2, w, horizonY, fovMult);
      final Offset a1RO = _project(astroOuterW + s1, y1 + 0.02, z1, w, horizonY, fovMult);
      final Offset a2RO = _project(astroOuterW + s2, y2 + 0.02, z2, w, horizonY, fovMult);
      final Offset k1LO = _project(-kerbOuterW + s1, y1 + 0.055, z1, w, horizonY, fovMult);
      final Offset k2LO = _project(-kerbOuterW + s2, y2 + 0.055, z2, w, horizonY, fovMult);
      final Offset k1RO = _project(kerbOuterW + s1, y1 + 0.055, z1, w, horizonY, fovMult);
      final Offset k2RO = _project(kerbOuterW + s2, y2 + 0.055, z2, w, horizonY, fovMult);

      final Color astroCol = Color.lerp(const Color(0xFF1A5E32), circuit.skyBottom, fogMix)!;
      _drawQuad(canvas, a1LO, k1LO, k2LO, a2LO, astroCol);
      _drawQuad(canvas, k1RO, a1RO, a2RO, k2RO, astroCol);

      final Offset p1L = _project(-roadHalfW + s1, y1, z1, w, horizonY, fovMult);
      final Offset p1R = _project(roadHalfW + s1, y1, z1, w, horizonY, fovMult);
      final Offset p2L = _project(-roadHalfW + s2, y2, z2, w, horizonY, fovMult);
      final Offset p2R = _project(roadHalfW + s2, y2, z2, w, horizonY, fovMult);

      final Color kerbCol = Color.lerp(segIndex % 2 == 0 ? circuit.kerbA : circuit.kerbB, circuit.skyBottom, fogMix)!;
      _drawQuad(canvas, k1LO, p1L, p2L, k2LO, kerbCol);
      _drawQuad(canvas, p1R, k1RO, k2RO, p2R, kerbCol);

      final bool isStartLine = lapDist1 < 5.2;
      final Color rawAsphalt = isStartLine
          ? const Color(0xFFF0F4F8)
          : (segIndex % 2 == 0 ? const Color(0xFF333842) : const Color(0xFF2D323B));
      final Color asphaltCol = Color.lerp(rawAsphalt, circuit.skyBottom, fogMix)!;
      _drawQuad(canvas, p1L, p1R, p2R, p2L, asphaltCol);

      if (isStartLine && i < 45) {
        final bool alt = (lapDist1 / 2.6).floor() % 2 == 0;
        for (int sq = 0; sq < 6; sq++) {
          if ((sq % 2 == 0) == alt) {
            final double xA = -roadHalfW + (sq * (roadHalfW * 2 / 6));
            final double xB = xA + (roadHalfW * 2 / 6);
            _drawQuad(
              canvas,
              _project(xA + s1, y1, z1, w, horizonY, fovMult),
              _project(xB + s1, y1, z1, w, horizonY, fovMult),
              _project(xB + s2, y2, z2, w, horizonY, fovMult),
              _project(xA + s2, y2, z2, w, horizonY, fovMult),
              Color.lerp(const Color(0xFF141820), circuit.skyBottom, fogMix)!,
            );
          }
        }
      }

      if (i < 58) {
        _asphaltClipPath
          ..moveTo(p1L.dx, p1L.dy)
          ..lineTo(p1R.dx, p1R.dy)
          ..lineTo(p2R.dx, p2R.dy)
          ..lineTo(p2L.dx, p2L.dy)
          ..close();
      }

      if (!isStartLine) {
        final Offset g1L = _project(-1.55 + s1, y1, z1, w, horizonY, fovMult);
        final Offset g1R = _project(1.55 + s1, y1, z1, w, horizonY, fovMult);
        final Offset g2L = _project(-1.55 + s2, y2, z2, w, horizonY, fovMult);
        final Offset g2R = _project(1.55 + s2, y2, z2, w, horizonY, fovMult);
        _drawQuad(canvas, g1L, g1R, g2R, g2L, Color.fromARGB((28 * (1.0 - fogMix)).toInt(), 0, 0, 0));

        final Offset sh1L = _project(-0.46 + s1, y1, z1, w, horizonY, fovMult);
        final Offset sh1R = _project(0.46 + s1, y1, z1, w, horizonY, fovMult);
        final Offset sh2L = _project(-0.46 + s2, y2, z2, w, horizonY, fovMult);
        final Offset sh2R = _project(0.46 + s2, y2, z2, w, horizonY, fovMult);
        _drawQuad(
          canvas,
          sh1L,
          sh1R,
          sh2R,
          sh2L,
          Color.fromARGB(((circuit.nightMode ? 34 : 22) * (1.0 - fogMix)).toInt(), 255, 255, 255),
        );
      }

      _strokePaint
        ..color = Color.lerp(const Color(0xF5F7FAFE), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(1.0, 4.4 / z1);
      canvas.drawLine(p1L, p2L, _strokePaint);
      canvas.drawLine(p1R, p2R, _strokePaint);

      if (i % 15 == 0 && i > 4 && i < 70) {
        final double aheadK = _curveAtWorldDist(worldDist1 + 95.0);
        if (aheadK.abs() > 1.35) {
          final bool onLeft = aheadK > 0;
          final double bx = (onLeft ? -runoffHalfW + 0.35 : runoffHalfW - 0.35) + s1;
          final String distTxt = i > 45 ? '150' : (i > 24 ? '100' : '50');
          _drawBrakingBoard(canvas, bx, y1, z1, w, horizonY, fovMult, distTxt, fogMix);
        }
      }

      if (i % 12 == 0 && i < segCount - 10) {
        _drawTracksideProp(canvas, -runoffHalfW - 1.8 + s1, y1, z1, w, horizonY, fovMult, fogMix, circuit);
        _drawTracksideProp(canvas, runoffHalfW + 1.8 + s1, y1, z1, w, horizonY, fovMult, fogMix, circuit);
      }

      if (isStartLine && i > 3 && i < 78) {
        _drawStartGantry(canvas, s1, y1, z1, roadHalfW, w, horizonY, fovMult, fogMix, circuit);
      }
    }

    if (UltraTextures.asphaltGrainShader != null) {
      canvas.save();
      canvas.clipPath(_asphaltClipPath);
      final double scrollY = (engine.playerDist * 24.0) % 256.0;
      canvas.translate(0, scrollY);
      canvas.drawRect(
        Rect.fromLTWH(0, horizonY - 256, w, h - horizonY + 512),
        Paint()..shader = UltraTextures.asphaltGrainShader..filterQuality = FilterQuality.high,
      );
      canvas.restore();
    }

    canvas.drawRect(
      Rect.fromLTWH(0, horizonY - 14, w, 30),
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [
            circuit.skyBottom.withAlpha(0),
            circuit.skyBottom.withAlpha(168),
            circuit.skyBottom.withAlpha(0),
          ],
        ).createShader(Rect.fromLTWH(0, horizonY - 14, w, 30)),
    );

    // 4. High-Resolution Rival F1 Cars (rendered cleanly down to z = 0.72 so no invisible pop-out before contact!)
    if (engine.phase == SessionPhase.race) {
      _visibleRivals.clear();
      for (final ai in engine.aiDrivers) {
        final double dz = (ai.trackDist - engine.playerDist) / 2.0;
        if (dz > 0.72 && dz < 92.0) {
          _visibleRivals.add(ai);
        }
      }
      _visibleRivals.sort((a, b) => b.trackDist.compareTo(a.trackDist));

      for (final ai in _visibleRivals) {
        final double z = (ai.trackDist - engine.playerDist) / 2.0;
        int idx = 1;
        for (int s = 1; s < segCount; s++) {
          if (_segZ[s] >= z) {
            idx = s;
            break;
          }
        }
        final double rx = (ai.laneX * RaceEngineState.kLaneToWorldX) + _segShift[idx] - camShift;
        final double ry = baseCamHeight + _segElev[idx];
        final Offset pos = _project(rx, ry, z, w, horizonY, fovMult);
        final double sc = (w * fovMult) / max(z, 0.45);
        final double viewParallax = ((pos.dx - w * 0.5) / (w * 0.5)).clamp(-1.0, 1.0).toDouble();
        _drawRivalF1CarUltraHD(canvas, pos, sc, viewParallax, ai);
      }
    }

    // 5. Sparks & Gravel Particles
    for (final p in engine.particles) {
      final Offset pt = Offset(p.x * w, p.y * h);
      if (p.isSpark) {
        _strokePaint
          ..color = p.color
          ..strokeWidth = p.radius
          ..strokeCap = StrokeCap.round;
        canvas.drawLine(pt, Offset(pt.dx - p.vx * 12, pt.dy - p.vy * 12), _strokePaint);
      } else {
        _fillPaint.color = p.color;
        canvas.drawCircle(pt, p.radius, _fillPaint);
      }
    }

    canvas.restore();

    // 6. Photorealistic Sculpted Cockpit OR Chase Car
    if (cockpit) {
      _drawCockpitUltra(canvas, w, h, circuit);
    } else {
      _drawChaseCarUltra(canvas, w, h);
    }

    // 7. Speed Motion Streaks
    final bool ersOn = engine.ersActive;
    if (engine.speedKmh > 245 || ersOn || engine.playerInSlipstream) {
      final double alphaFrac = ((engine.speedKmh - 235) / 115.0).clamp(0.14, 0.72).toDouble();
      _strokePaint
        ..color = ersOn
            ? Color.fromARGB((alphaFrac * 120).toInt(), 0, 229, 255)
            : (engine.playerInSlipstream
                ? Color.fromARGB((alphaFrac * 105).toInt(), 105, 240, 174)
                : Color.fromARGB((alphaFrac * 90).toInt(), 255, 255, 255))
        ..strokeWidth = 1.7;
      for (int k = 0; k < 12; k++) {
        final double lx = (k.isEven ? 0.03 + (k * 0.009) : 0.97 - (k * 0.009)) * w;
        final double ly = ((engine.playerDist * 28 + k * 60) % h);
        canvas.drawLine(Offset(lx, ly), Offset(lx, ly + 44), _strokePaint);
      }
    }

    if (_vignettePaint != null) {
      canvas.drawRect(Rect.fromLTWH(0, 0, w, h), _vignettePaint!);
    }

    if (engine.hitFlash > 0) {
      canvas.drawRect(
        Rect.fromLTWH(0, 0, w, h),
        Paint()
          ..shader = RadialGradient(
            radius: 0.95,
            colors: [
              const Color(0x00FF0000),
              Color.fromARGB((engine.hitFlash * 160).toInt(), 255, 18, 18),
            ],
          ).createShader(Rect.fromLTWH(0, 0, w, h)),
      );
    }
  }

  void _drawQuad(Canvas canvas, Offset a, Offset b, Offset c, Offset d, Color color) {
    _quadPath
      ..reset()
      ..moveTo(a.dx, a.dy)
      ..lineTo(b.dx, b.dy)
      ..lineTo(c.dx, c.dy)
      ..lineTo(d.dx, d.dy)
      ..close();
    _fillPaint.color = color;
    canvas.drawPath(_quadPath, _fillPaint);
  }

  void _drawBrakingBoard(
    Canvas canvas,
    double x,
    double y1,
    double z,
    double w,
    double horizonY,
    double fovMult,
    String text,
    double fogMix,
  ) {
    final Offset base = _project(x, y1, z, w, horizonY, fovMult);
    final Offset top = _project(x, y1 + 1.38, z, w, horizonY, fovMult);
    final double bh = max(6.0, base.dy - top.dy);
    final double bw = bh * 1.15;
    if (bw < 8.0) return;

    final Rect board = Rect.fromLTWH(top.dx - bw * 0.5, top.dy, bw, bh * 0.68);
    _fillPaint.color = Color.lerp(const Color(0xFFF5F7FA), engine.circuit.skyBottom, fogMix)!;
    canvas.drawRect(board, _fillPaint);
    _strokePaint
      ..color = Color.lerp(const Color(0xFFE10600), engine.circuit.skyBottom, fogMix)!
      ..strokeWidth = max(1.0, bw * 0.08);
    canvas.drawRect(board, _strokePaint);
    if (bw > 16.0) {
      _drawCenteredText(canvas, text, board.center, (bh * 0.34).clamp(7.0, 14.0).toDouble(), const Color(0xFF11141A), FontWeight.w900);
    }
  }

  void _drawProEnvironment(Canvas canvas, double w, double h, double horizonY, CircuitInfo circuit) {
    final Color skyMid = Color.lerp(circuit.skyTop, circuit.skyBottom, 0.56)!;
    canvas.drawRect(
      Rect.fromLTWH(0, 0, w, horizonY),
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          stops: const [0.0, 0.52, 1.0],
          colors: [circuit.skyTop, skyMid, circuit.skyBottom],
        ).createShader(Rect.fromLTWH(0, 0, w, horizonY)),
    );

    final double sunX = ((w * 0.72 + engine.horizonPan * 0.14) % (w * 1.4)) - w * 0.2;
    final Offset sunCenter = Offset(sunX, horizonY * 0.38);
    final double haloR = circuit.nightMode ? 52.0 : 150.0;
    canvas.drawCircle(
      sunCenter,
      haloR,
      Paint()
        ..shader = RadialGradient(
          colors: circuit.nightMode
              ? const [Color(0xBBEBF5FF), Color(0x38A3CFFF), Color(0x00000000)]
              : const [Color(0xEEFFFCE8), Color(0x68FFD285), Color(0x00FFD285)],
        ).createShader(Rect.fromCircle(center: sunCenter, radius: haloR)),
    );

    if (circuit.nightMode) {
      _fillPaint.color = const Color(0xAAFFFFFF);
      for (int s = 0; s < 36; s++) {
        final double sx = ((s * 97.0 + engine.horizonPan * 0.08) % w + w) % w;
        final double sy = (s * 27.0) % (horizonY * 0.65);
        canvas.drawCircle(Offset(sx, sy), (s % 3 == 0) ? 1.4 : 0.9, _fillPaint);
      }
    } else {
      for (int c = 0; c < 6; c++) {
        final double cx = ((c * 240.0 + engine.horizonPan * 0.18) % (w + 280)) - 140;
        final double cy = horizonY * (0.20 + (c % 3) * 0.15);
        final Rect cr = Rect.fromCenter(center: Offset(cx, cy), width: 215, height: 34);
        canvas.drawOval(
          cr,
          Paint()..shader = const RadialGradient(colors: [Color(0x48FFFFFF), Color(0x00FFFFFF)]).createShader(cr),
        );
      }
    }

    _backRangePath
      ..reset()
      ..moveTo(0, horizonY);
    for (double x = 0; x <= w + 40; x += 32) {
      final double wx = x - engine.horizonPan * 0.24;
      final double pk = 24.0 + sin(wx * 0.009) * 20.0 + cos(wx * 0.023) * 11.0;
      _backRangePath.lineTo(x, horizonY - pk);
    }
    _backRangePath
      ..lineTo(w, horizonY)
      ..close();
    _fillPaint.color = Color.lerp(circuit.nightMode ? const Color(0xFF0A1020) : const Color(0xFF31445C), circuit.skyBottom, 0.45)!;
    canvas.drawPath(_backRangePath, _fillPaint);

    _frontRangePath
      ..reset()
      ..moveTo(0, horizonY);
    for (double x = 0; x <= w + 40; x += 34) {
      final double wx = x - engine.horizonPan * 0.36;
      final double pk = circuit.propStyle == PropStyle.skyline
          ? (22.0 + ((wx ~/ 40).abs() % 6) * 14.0)
          : (15.0 + sin(wx * 0.015 + 1.2) * 15.0 + cos(wx * 0.032) * 8.0);
      _frontRangePath.lineTo(x, horizonY - pk);
    }
    _frontRangePath
      ..lineTo(w, horizonY)
      ..close();
    _fillPaint.color = Color.lerp(circuit.nightMode ? const Color(0xFF0F172B) : const Color(0xFF233245), circuit.skyBottom, 0.24)!;
    canvas.drawPath(_frontRangePath, _fillPaint);

    final double gsX = ((w * 0.03 + engine.horizonPan * 0.50) % (w * 1.6)) - w * 0.3;
    final double gsW = w * 0.62;
    final double gsTop = horizonY - 54;
    final Rect gsRect = Rect.fromLTWH(gsX, gsTop, gsW, 54);
    canvas.drawRect(
      gsRect,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: circuit.nightMode
              ? const [Color(0xFF1A243B), Color(0xFF0B101B)]
              : const [Color(0xFF4F5A6B), Color(0xFF222833)],
        ).createShader(gsRect),
    );
    if (UltraTextures.crowdShader != null) {
      canvas.save();
      final Rect crowdArea = Rect.fromLTWH(gsX + 4, gsTop + 14, gsW - 8, 38);
      canvas.clipRect(crowdArea);
      canvas.translate(gsX, gsTop + 14);
      canvas.drawRect(Rect.fromLTWH(0, 0, gsW, 38), Paint()..shader = UltraTextures.crowdShader);
      canvas.restore();
    }
    _fillPaint.color = circuit.nightMode ? const Color(0xAA40C4FF) : const Color(0x74B3E5FC);
    canvas.drawRect(Rect.fromLTWH(gsX + 4, gsTop + 3, gsW - 8, 9), _fillPaint);
    _fillPaint.color = circuit.nightMode ? const Color(0xFF334366) : const Color(0xFF8F9BAB);
    canvas.drawRect(Rect.fromLTWH(gsX - 12, gsTop - 8, gsW + 24, 9), _fillPaint);

    _strokePaint
      ..color = const Color(0xFF171C26)
      ..strokeWidth = 3.2;
    for (int p = 0; p <= 7; p++) {
      final double px = gsX + (gsW / 7) * p;
      canvas.drawLine(Offset(px, gsTop), Offset(px, horizonY), _strokePaint);
    }
  }

  void _drawStartGantry(
    Canvas canvas,
    double s1,
    double y1,
    double z1,
    double roadHalfW,
    double w,
    double horizonY,
    double fovMult,
    double fogMix,
    CircuitInfo circuit,
  ) {
    final Offset bL = _project(-roadHalfW - 0.85 + s1, y1, z1, w, horizonY, fovMult);
    final Offset bR = _project(roadHalfW + 0.85 + s1, y1, z1, w, horizonY, fovMult);
    final Offset tL = _project(-roadHalfW - 0.85 + s1, y1 + 3.6, z1, w, horizonY, fovMult);
    final Offset tR = _project(roadHalfW + 0.85 + s1, y1 + 3.6, z1, w, horizonY, fovMult);
    final double beamH = max(5.0, 58.0 / z1);

    _strokePaint
      ..color = Color.lerp(const Color(0xFF1B212C), circuit.skyBottom, fogMix)!
      ..strokeWidth = max(3.0, 26.0 / z1);
    canvas.drawLine(bL, tL, _strokePaint);
    canvas.drawLine(bR, tR, _strokePaint);

    final Rect bridge = Rect.fromLTRB(tL.dx, tL.dy - beamH * 0.5, tR.dx, tR.dy + beamH * 0.5);
    _fillPaint.color = Color.lerp(const Color(0xFF101520), circuit.skyBottom, fogMix)!;
    canvas.drawRect(bridge, _fillPaint);
    _fillPaint.color = Color.lerp(const Color(0xFFE10600), circuit.skyBottom, fogMix)!;
    canvas.drawRect(Rect.fromLTRB(tL.dx, tL.dy - beamH * 0.5, tR.dx, tL.dy - beamH * 0.22), _fillPaint);
  }

  void _drawTracksideProp(
    Canvas canvas,
    double x,
    double y1,
    double z,
    double w,
    double horizonY,
    double fovMult,
    double fogMix,
    CircuitInfo circuit,
  ) {
    final Offset base = _project(x, y1, z, w, horizonY, fovMult);
    final Offset top = _project(x, y1 + 4.0, z, w, horizonY, fovMult);
    final double ph = max(8.0, base.dy - top.dy);
    final double pw = max(6.0, ph * 0.52);

    if (circuit.propStyle == PropStyle.palms) {
      _strokePaint
        ..color = Color.lerp(const Color(0xFF5D4037), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(2.2, pw * 0.16);
      canvas.drawLine(base, top, _strokePaint);
      _strokePaint
        ..color = Color.lerp(circuit.nightMode ? const Color(0xFF1C4F30) : const Color(0xFF2B6E33), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(2.0, pw * 0.14)
        ..strokeCap = StrokeCap.round;
      for (int a = 0; a < 7; a++) {
        final double ang = -pi + (a * pi / 6);
        canvas.drawLine(top, Offset(top.dx + cos(ang) * pw * 0.95, top.dy + sin(ang) * pw * 0.45 + 4), _strokePaint);
      }
    } else if (circuit.propStyle == PropStyle.skyline) {
      final Rect bldg = Rect.fromLTWH(top.dx - pw * 0.65, top.dy - ph * 0.35, pw * 1.3, ph * 1.35);
      _fillPaint.color = Color.lerp(circuit.nightMode ? const Color(0xFF161E33) : const Color(0xFF384257), circuit.skyBottom, fogMix)!;
      canvas.drawRect(bldg, _fillPaint);
      if (pw > 14) {
        _fillPaint.color = circuit.nightMode ? const Color(0xCC00E5FF) : const Color(0x66FFF0A6);
        for (int r = 0; r < 3; r++) {
          canvas.drawRect(Rect.fromLTWH(bldg.left + pw * 0.2, bldg.top + ph * (0.2 + r * 0.25), pw * 0.9, ph * 0.09), _fillPaint);
        }
      }
    } else if (circuit.propStyle == PropStyle.trees) {
      _strokePaint
        ..color = Color.lerp(const Color(0xFF4E342E), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(2.2, pw * 0.18);
      canvas.drawLine(base, Offset(top.dx, base.dy - ph * 0.42), _strokePaint);
      _fillPaint.color = Color.lerp(const Color(0xFF18441E), circuit.skyBottom, fogMix)!;
      canvas.drawCircle(Offset(top.dx, base.dy - ph * 0.65), pw * 0.56, _fillPaint);
      _fillPaint.color = Color.lerp(const Color(0xFF35783A), circuit.skyBottom, fogMix)!;
      canvas.drawCircle(Offset(top.dx - pw * 0.15, base.dy - ph * 0.72), pw * 0.36, _fillPaint);
    } else {
      _strokePaint
        ..color = Color.lerp(const Color(0xFF90A4AE), circuit.skyBottom, fogMix)!
        ..strokeWidth = max(1.8, pw * 0.12);
      canvas.drawLine(base, top, _strokePaint);
      if (circuit.nightMode) {
        final double glowR = max(6.0, pw * 0.55);
        canvas.drawCircle(
          top,
          glowR,
          Paint()
            ..shader = const RadialGradient(
              colors: [Color(0xEEFFFFFF), Color(0x44FFFDE7), Color(0x00FFFDE7)],
            ).createShader(Rect.fromCircle(center: top, radius: glowR)),
        );
      }
    }
  }

  /// Ultra-High-Definition Modern F1 Rival Car (1:1 aligned to collision hitbox width!)
  void _drawRivalF1CarUltraHD(Canvas canvas, Offset pos, double sc, double parallax, AiDriver ai) {
    final double cw = (sc * RaceEngineState.kRivalVisualScale).clamp(11.0, 290.0).toDouble();
    final double ch = (sc * 0.54).clamp(5.5, 130.0).toDouble();
    final double shift3d = -parallax * cw * 0.18;

    canvas.save();
    if (ai.steerTilt.abs() > 0.005) {
      canvas.translate(pos.dx, pos.dy);
      canvas.rotate(ai.steerTilt * 0.35);
      canvas.translate(-pos.dx, -pos.dy);
    }

    // 1. Grounded Ambient Occlusion Shadow
    final Rect shadRect = Rect.fromCenter(center: Offset(pos.dx, pos.dy + ch * 0.05), width: cw * 1.66, height: ch * 0.44);
    canvas.drawOval(
      shadRect,
      Paint()
        ..shader = const RadialGradient(
          colors: [Color(0xE2000000), Color(0x8A000000), Color(0x00000000)],
        ).createShader(shadRect),
    );

    // 2. Front Wheels + Front Wing Tips peeking ahead in 3D Perspective
    if (cw > 24) {
      final double ftW = cw * 0.18;
      final double ftH = ch * 0.62;
      _fillPaint.color = const Color(0xFF11141A);
      canvas.drawRRect(
        RRect.fromRectAndRadius(Rect.fromLTWH(pos.dx + shift3d * 1.35 - cw * 0.57, pos.dy - ch * 0.90, ftW, ftH), Radius.circular(cw * 0.04)),
        _fillPaint,
      );
      canvas.drawRRect(
        RRect.fromRectAndRadius(Rect.fromLTWH(pos.dx + shift3d * 1.35 + cw * 0.39, pos.dy - ch * 0.90, ftW, ftH), Radius.circular(cw * 0.04)),
        _fillPaint,
      );
    }

    // 3. Carbon Venturi Floor Plank + Outer Edge Wings + High-Speed Skid Sparks
    _fillPaint.color = const Color(0xFF0E1117);
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(pos.dx - cw * 0.56, pos.dy - ch * 0.24, cw * 1.12, ch * 0.22), Radius.circular(cw * 0.03)),
      _fillPaint,
    );
    if (cw > 48 && ai.currentSpeedKmh > 290 && ((engine.totalRaceTime * 18 + ai.trackDist).floor() % 7 == 0)) {
      _fillPaint.color = const Color(0xDDFFCA28);
      canvas.drawCircle(Offset(pos.dx - cw * 0.1, pos.dy - ch * 0.04), max(1.6, cw * 0.018), _fillPaint);
      canvas.drawCircle(Offset(pos.dx + cw * 0.14, pos.dy - ch * 0.02), max(1.4, cw * 0.014), _fillPaint);
    }

    // 4. Sculpted Wide Rear Slick Tires + 3D Rubber Tread + Brake Ducts + Red Pirelli Sidewall + Spinning Rim Detail
    final RRect tireL = RRect.fromRectAndRadius(
      Rect.fromLTWH(pos.dx - cw * 0.74, pos.dy - ch * 0.98, cw * 0.30, ch * 0.98),
      Radius.circular(cw * 0.065),
    );
    final RRect tireR = RRect.fromRectAndRadius(
      Rect.fromLTWH(pos.dx + cw * 0.44, pos.dy - ch * 0.98, cw * 0.30, ch * 0.98),
      Radius.circular(cw * 0.065),
    );
    canvas.drawRRect(
      tireL,
      Paint()
        ..isAntiAlias = true
        ..shader = const LinearGradient(
          stops: [0.0, 0.22, 0.52, 0.82, 1.0],
          colors: [Color(0xFF07090C), Color(0xFF282F3B), Color(0xFF454F61), Color(0xFF1F242E), Color(0xFF0A0C10)],
        ).createShader(tireL.outerRect),
    );
    canvas.drawRRect(
      tireR,
      Paint()
        ..isAntiAlias = true
        ..shader = const LinearGradient(
          stops: [0.0, 0.18, 0.48, 0.78, 1.0],
          colors: [Color(0xFF0A0C10), Color(0xFF1F242E), Color(0xFF454F61), Color(0xFF282F3B), Color(0xFF07090C)],
        ).createShader(tireR.outerRect),
    );
    if (cw > 38) {
      // Tire rubber rotation bands
      final double treadPhase = (ai.trackDist * 0.65) % 1.0;
      _strokePaint..color = const Color(0x36000000)..strokeWidth = max(1.0, ch * 0.045);
      for (int b = 0; b < 3; b++) {
        final double ty = tireL.top + ((b / 3.0 + treadPhase) % 1.0) * ch * 0.86 + ch * 0.05;
        canvas.drawLine(Offset(tireL.left + 2, ty), Offset(tireL.right - 2, ty), _strokePaint);
        canvas.drawLine(Offset(tireR.left + 2, ty), Offset(tireR.right - 2, ty), _strokePaint);
      }
      // Red Pirelli sidewall accents & inner carbon brake ducts
      _strokePaint..color = const Color(0xDDE10600)..strokeWidth = max(1.2, cw * 0.018);
      canvas.drawLine(Offset(tireL.left + 1.5, tireL.top + ch * 0.20), Offset(tireL.left + 1.5, tireL.bottom - ch * 0.20), _strokePaint);
      canvas.drawLine(Offset(tireR.right - 1.5, tireR.top + ch * 0.20), Offset(tireR.right - 1.5, tireR.bottom - ch * 0.20), _strokePaint);
      // Glowing brake caliper inside rear wheel when braking heavily!
      if (ai.isBraking) {
        _fillPaint.color = const Color(0xCCFF5722);
        canvas.drawCircle(Offset(tireL.right + 1.5, pos.dy - ch * 0.48), cw * 0.04, _fillPaint);
        canvas.drawCircle(Offset(tireR.left - 1.5, pos.dy - ch * 0.48), cw * 0.04, _fillPaint);
      }
    }

    // 5. Rear Multi-Link Carbon Suspension + Multi-Channel Venturi Diffuser + Metallic Exhaust
    _strokePaint..color = const Color(0xFF1A202B)..strokeWidth = max(1.3, ch * 0.08);
    canvas.drawLine(Offset(pos.dx - cw * 0.45, pos.dy - ch * 0.56), Offset(pos.dx - cw * 0.20, pos.dy - ch * 0.50), _strokePaint);
    canvas.drawLine(Offset(pos.dx + cw * 0.45, pos.dy - ch * 0.56), Offset(pos.dx + cw * 0.20, pos.dy - ch * 0.50), _strokePaint);
    _strokePaint..color = const Color(0xFF12161E)..strokeWidth = max(1.1, ch * 0.06);
    canvas.drawLine(Offset(pos.dx - cw * 0.45, pos.dy - ch * 0.36), Offset(pos.dx - cw * 0.22, pos.dy - ch * 0.34), _strokePaint);
    canvas.drawLine(Offset(pos.dx + cw * 0.45, pos.dy - ch * 0.36), Offset(pos.dx + cw * 0.22, pos.dy - ch * 0.34), _strokePaint);

    final Rect diffRect = Rect.fromLTWH(pos.dx - cw * 0.41, pos.dy - ch * 0.39, cw * 0.82, ch * 0.37);
    _fillPaint.color = const Color(0xFF10131A);
    canvas.drawRect(diffRect, _fillPaint);
    if (cw > 34) {
      _strokePaint..color = const Color(0xFF3E495C)..strokeWidth = max(1.0, cw * 0.014);
      for (final double frac in const [-0.28, -0.14, 0.14, 0.28]) {
        canvas.drawLine(Offset(pos.dx + cw * frac, diffRect.top + 1), Offset(pos.dx + cw * frac, diffRect.bottom), _strokePaint);
      }
      // Central metallic tailpipe + twin wastegate ports
      _fillPaint.color = const Color(0xFF8C9BB0);
      canvas.drawCircle(Offset(pos.dx, pos.dy - ch * 0.57), cw * 0.056, _fillPaint);
      _fillPaint.color = const Color(0xFF0A0C10);
      canvas.drawCircle(Offset(pos.dx, pos.dy - ch * 0.57), cw * 0.033, _fillPaint);
    }

    // 6. Sculpted Coke-Bottle Sidepods, Undercut Cooling Louvers & Clearcoat Metallic Engine Cover
    final Path sidepods = Path()
      ..moveTo(pos.dx - cw * 0.47, pos.dy - ch * 0.30)
      ..quadraticBezierTo(pos.dx - cw * 0.47 + shift3d * 0.4, pos.dy - ch * 0.84, pos.dx - cw * 0.28 + shift3d * 0.6, pos.dy - ch * 1.02)
      ..quadraticBezierTo(pos.dx + shift3d * 0.7, pos.dy - ch * 1.28, pos.dx + cw * 0.28 + shift3d * 0.6, pos.dy - ch * 1.02)
      ..quadraticBezierTo(pos.dx + cw * 0.47 + shift3d * 0.4, pos.dy - ch * 0.84, pos.dx + cw * 0.47, pos.dy - ch * 0.30)
      ..close();
    canvas.drawPath(
      sidepods,
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          stops: const [0.0, 0.32, 0.78, 1.0],
          colors: [ai.bodyHighlight, ai.bodyColor, Color.lerp(ai.bodyColor, Colors.black, 0.48)!, const Color(0xFF080A0E)],
        ).createShader(Rect.fromLTWH(pos.dx - cw * 0.47, pos.dy - ch * 1.28, cw * 0.94, ch * 1.00)),
    );

    // Sidepod dark radiator undercut vents + glossy clearcoat shoulder highlight
    if (cw > 36) {
      _fillPaint.color = const Color(0x99080A0F);
      canvas.drawOval(Rect.fromCenter(center: Offset(pos.dx - cw * 0.30 + shift3d * 0.3, pos.dy - ch * 0.62), width: cw * 0.16, height: ch * 0.22), _fillPaint);
      canvas.drawOval(Rect.fromCenter(center: Offset(pos.dx + cw * 0.30 + shift3d * 0.3, pos.dy - ch * 0.62), width: cw * 0.16, height: ch * 0.22), _fillPaint);

      _strokePaint..color = const Color(0x80FFFFFF)..strokeWidth = max(1.1, cw * 0.018);
      canvas.drawPath(
        Path()
          ..moveTo(pos.dx - cw * 0.26 + shift3d * 0.6, pos.dy - ch * 0.98)
          ..quadraticBezierTo(pos.dx + shift3d * 0.7, pos.dy - ch * 1.18, pos.dx + cw * 0.26 + shift3d * 0.6, pos.dy - ch * 0.98),
        _strokePaint,
      );
      // Center racing livery accent stripe down engine spine
      _strokePaint..color = ai.wingColor.withAlpha(210)..strokeWidth = max(1.2, cw * 0.032);
      canvas.drawLine(Offset(pos.dx + shift3d * 0.75, pos.dy - ch * 1.16), Offset(pos.dx, pos.dy - ch * 0.68), _strokePaint);
    }

    // 7. Driver Helmet + Visor + Halo Hoop + Sculpted Airbox + Shark Fin + T-Cam
    final double topX = pos.dx + shift3d * 0.9;
    _fillPaint.color = ai.helmetColor;
    canvas.drawCircle(Offset(topX, pos.dy - ch * 1.22), cw * 0.105, _fillPaint);
    if (cw > 42) {
      // Metallic dark visor strip on helmet
      _fillPaint.color = const Color(0xDD0A0E17);
      canvas.drawRect(Rect.fromCenter(center: Offset(topX, pos.dy - ch * 1.24), width: cw * 0.16, height: ch * 0.06), _fillPaint);
    }
    if (cw > 34) {
      _strokePaint..color = const Color(0xFF161A22)..strokeWidth = max(1.5, cw * 0.026);
      canvas.drawArc(
        Rect.fromCenter(center: Offset(topX, pos.dy - ch * 1.18), width: cw * 0.33, height: ch * 0.44),
        pi,
        pi,
        false,
        _strokePaint,
      );
    }
    // Airbox scoop + intake hole
    _fillPaint.color = ai.bodyColor;
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(topX - cw * 0.09, pos.dy - ch * 1.54, cw * 0.18, ch * 0.38), Radius.circular(cw * 0.045)),
      _fillPaint,
    );
    _fillPaint.color = const Color(0xFF141820);
    canvas.drawRect(Rect.fromLTWH(topX - cw * 0.15, pos.dy - ch * 1.60, cw * 0.30, ch * 0.068), _fillPaint);

    // 8. Dual-Element Sculpted Rear Wing + Swan-Neck Pillar + Animated DRS Flap + Endplate Cutouts
    _fillPaint.color = const Color(0xFF161A22);
    canvas.drawRect(Rect.fromLTWH(pos.dx - cw * 0.45, pos.dy - ch * 0.76, cw * 0.90, ch * 0.11), _fillPaint);
    canvas.drawRect(Rect.fromLTWH(pos.dx - cw * 0.03, pos.dy - ch * 1.26, cw * 0.06, ch * 0.62), _fillPaint);

    // Lower Wing Mainplane
    final Rect mainplane = Rect.fromLTWH(pos.dx - cw * 0.51, pos.dy - ch * 1.22, cw * 1.02, ch * 0.12);
    canvas.drawRect(
      mainplane,
      Paint()
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [ai.wingColor, Color.lerp(ai.wingColor, Colors.black, 0.38)!],
        ).createShader(mainplane),
    );

    // Upper DRS Flap (opens visibly with bright sky gap when AI deploys DRS!)
    final double flapHeight = ai.drsOpen ? ch * 0.065 : ch * 0.13;
    final double flapTop = ai.drsOpen ? (pos.dy - ch * 1.42) : (pos.dy - ch * 1.36);
    final RRect drsFlap = RRect.fromRectAndRadius(
      Rect.fromLTWH(pos.dx - cw * 0.51, flapTop, cw * 1.02, flapHeight),
      Radius.circular(cw * 0.02),
    );
    canvas.drawRRect(
      drsFlap,
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: ai.drsOpen
              ? [const Color(0xFF99F7FF), ai.wingColor]
              : [Color.lerp(ai.wingColor, Colors.white, 0.28)!, ai.wingColor],
        ).createShader(drsFlap.outerRect),
    );

    // Sculpted Rear Wing Endplates + Livery Stripe
    _fillPaint.color = const Color(0xFF151922);
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(pos.dx - cw * 0.55, pos.dy - ch * 1.42, cw * 0.07, ch * 0.64), Radius.circular(cw * 0.02)), _fillPaint);
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(pos.dx + cw * 0.48, pos.dy - ch * 1.42, cw * 0.07, ch * 0.64), Radius.circular(cw * 0.02)), _fillPaint);
    if (cw > 42) {
      _fillPaint.color = ai.bodyColor;
      canvas.drawRect(Rect.fromLTWH(pos.dx - cw * 0.54, pos.dy - ch * 1.36, cw * 0.05, ch * 0.24), _fillPaint);
      canvas.drawRect(Rect.fromLTWH(pos.dx + cw * 0.49, pos.dy - ch * 1.36, cw * 0.05, ch * 0.24), _fillPaint);
    }

    // 9. Flashing FIA Rain / ERS Braking Light
    final bool flashOn = ai.isBraking || ((engine.totalRaceTime * 6.0).floor() % 2 == 0);
    final Offset lightC = Offset(pos.dx, pos.dy - ch * 0.39);
    if (flashOn) {
      final double lr = max(4.0, cw * (ai.isBraking ? 0.18 : 0.11));
      canvas.drawCircle(
        lightC,
        lr,
        Paint()
          ..shader = const RadialGradient(
            colors: [Color(0xFFFF3D5A), Color(0x66FF1744), Color(0x00FF1744)],
          ).createShader(Rect.fromCircle(center: lightC, radius: lr)),
      );
      _fillPaint.color = ai.isBraking ? const Color(0xFFFF8A9E) : const Color(0xFFFF4562);
      canvas.drawRect(Rect.fromCenter(center: lightC, width: cw * 0.075, height: ch * 0.18), _fillPaint);
    }

    canvas.restore();

    // 10. Cached Crisp 3-Letter Tag
    if (cw > 24) {
      final TextPainter tp = _getCachedTag(ai.code);
      final double bx = pos.dx - tp.width * 0.5 - 5;
      final double by = pos.dy - ch * 1.80 - tp.height;
      _fillPaint.color = const Color(0xC6070B12);
      canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(bx, by - 1, tp.width + 10, tp.height + 2), const Radius.circular(4)), _fillPaint);
      _fillPaint.color = ai.drsOpen ? const Color(0xFF00E5FF) : ai.bodyColor;
      canvas.drawRect(Rect.fromLTWH(bx, by - 1, 2.8, tp.height + 2), _fillPaint);
      tp.paint(canvas, Offset(bx + 5, by));
    }
  }

  void _drawCockpitUltra(Canvas canvas, double w, double h, CircuitInfo circuit) {
    final TeamLivery livery = engine.livery;
    final double cx = w * 0.5;
    final double offTrackShake = engine.carX.abs() > 1.02 ? (sin(engine.playerDist * 2.8) * 4.5) : 0.0;
    final double vib = sin(engine.playerDist * 0.9) * (engine.speedKmh / 320.0) * 1.2 + offTrackShake + engine.smoothPitch * 2.5;

    final Paint carbonPaint = UltraTextures.carbonShader != null
        ? (Paint()..isAntiAlias = true..shader = UltraTextures.carbonShader..filterQuality = FilterQuality.high)
        : (Paint()..isAntiAlias = true..color = const Color(0xFF14171E));

    final double wheelShift = engine.steerAngle * 18.0;

    final Paint wingPaint = Paint()
      ..isAntiAlias = true
      ..shader = LinearGradient(colors: [livery.primaryLight, livery.primaryDark]).createShader(Rect.fromLTWH(0, h * 0.57, w, 40));
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(w * 0.072 + wheelShift * 0.65, h * 0.592 + vib, w * 0.105, 11), const Radius.circular(3)),
      wingPaint,
    );
    canvas.drawRRect(
      RRect.fromRectAndRadius(Rect.fromLTWH(w * 0.823 + wheelShift * 0.65, h * 0.592 + vib, w * 0.105, 11), const Radius.circular(3)),
      wingPaint,
    );

    _drawFrontTireUltra(canvas, Offset(w * 0.172 + wheelShift, h * 0.72 + vib), w * 0.16, h * 0.315, true);
    _drawFrontTireUltra(canvas, Offset(w * 0.828 + wheelShift, h * 0.72 + vib), w * 0.16, h * 0.315, false);

    _strokePaint..color = const Color(0xFF1D222C)..strokeWidth = 6.5..strokeCap = StrokeCap.round;
    canvas.drawLine(Offset(w * 0.22 + wheelShift * 0.5, h * 0.675 + vib), Offset(w * 0.38, h * 0.735 + vib), _strokePaint);
    canvas.drawLine(Offset(w * 0.78 + wheelShift * 0.5, h * 0.675 + vib), Offset(w * 0.62, h * 0.735 + vib), _strokePaint);

    _strokePaint..color = const Color(0xFF0E1117)..strokeWidth = 8.4;
    canvas.drawLine(Offset(w * 0.23 + wheelShift * 0.5, h * 0.765 + vib), Offset(w * 0.40, h * 0.795 + vib), _strokePaint);
    canvas.drawLine(Offset(w * 0.77 + wheelShift * 0.5, h * 0.765 + vib), Offset(w * 0.60, h * 0.795 + vib), _strokePaint);

    _strokePaint..color = const Color(0xFF5D6B82)..strokeWidth = 3.2;
    canvas.drawLine(Offset(w * 0.24 + wheelShift * 0.5, h * 0.745 + vib), Offset(w * 0.39, h * 0.695 + vib), _strokePaint);
    canvas.drawLine(Offset(w * 0.76 + wheelShift * 0.5, h * 0.745 + vib), Offset(w * 0.61, h * 0.695 + vib), _strokePaint);

    final Path cowling = Path()
      ..moveTo(0, h * 0.695 + vib)
      ..quadraticBezierTo(w * 0.20, h * 0.605 + vib, w * 0.36, h * 0.725 + vib)
      ..lineTo(w * 0.64, h * 0.725 + vib)
      ..quadraticBezierTo(w * 0.80, h * 0.605 + vib, w, h * 0.695 + vib)
      ..lineTo(w, h)
      ..lineTo(0, h)
      ..close();
    canvas.drawPath(
      cowling,
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          stops: const [0.0, 0.18, 0.54, 1.0],
          colors: [livery.primaryLight, livery.primary, livery.primaryDark, const Color(0xFF080A0E)],
        ).createShader(Rect.fromLTWH(0, h * 0.60, w, h * 0.40)),
    );

    _strokePaint..color = const Color(0xAAFFFFFF)..strokeWidth = 2.6;
    canvas.drawPath(
      Path()
        ..moveTo(0, h * 0.695 + vib)
        ..quadraticBezierTo(w * 0.20, h * 0.605 + vib, w * 0.36, h * 0.725 + vib)
        ..lineTo(w * 0.64, h * 0.725 + vib)
        ..quadraticBezierTo(w * 0.80, h * 0.605 + vib, w, h * 0.695 + vib),
      _strokePaint,
    );

    _strokePaint..color = livery.secondary.withAlpha(215)..strokeWidth = 3.2;
    canvas.drawPath(
      Path()..moveTo(w * 0.03, h * 0.71 + vib)..quadraticBezierTo(w * 0.20, h * 0.64 + vib, w * 0.34, h * 0.74 + vib),
      _strokePaint,
    );
    canvas.drawPath(
      Path()..moveTo(w * 0.97, h * 0.71 + vib)..quadraticBezierTo(w * 0.80, h * 0.64 + vib, w * 0.66, h * 0.74 + vib),
      _strokePaint,
    );

    _drawSideMirrorUltra(canvas, Offset(w * 0.26, h * 0.65 + vib), true, engine.rivalCloseLeft, circuit);
    _drawSideMirrorUltra(canvas, Offset(w * 0.74, h * 0.65 + vib), false, engine.rivalCloseRight, circuit);

    final Path tub = Path()
      ..moveTo(w * 0.23, h * 0.745 + vib)
      ..lineTo(w * 0.77, h * 0.745 + vib)
      ..lineTo(w * 0.85, h)
      ..lineTo(w * 0.15, h)
      ..close();
    canvas.drawPath(tub, carbonPaint);
    canvas.drawPath(
      tub,
      Paint()
        ..shader = const LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [Color(0xCC000000), Color(0x35000000)],
        ).createShader(Rect.fromLTWH(w * 0.15, h * 0.745, w * 0.70, h * 0.255)),
    );

    final Path haloArch = Path()
      ..moveTo(0, 0)
      ..lineTo(w, 0)
      ..lineTo(w, h * 0.145)
      ..quadraticBezierTo(cx, h * 0.012, 0, h * 0.145)
      ..close();
    canvas.drawPath(
      haloArch,
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(
          begin: Alignment.topCenter,
          end: Alignment.bottomCenter,
          colors: [const Color(0xFF080A0F), livery.primaryDark, livery.primary],
        ).createShader(Rect.fromLTWH(0, 0, w, h * 0.155)),
    );

    final Path pillar = Path()
      ..moveTo(cx - 26, h * 0.04)
      ..lineTo(cx + 26, h * 0.04)
      ..lineTo(cx + 12, h * 0.73 + vib)
      ..lineTo(cx - 12, h * 0.73 + vib)
      ..close();
    canvas.drawPath(
      pillar,
