    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromCenter(center: Offset(cx, h * 0.16), width: 22, height: 28), const Radius.circular(6)), _fillPaint);
    _strokePaint..color = livery.primaryDark..strokeWidth = 1.6;
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromCenter(center: Offset(cx, h * 0.16), width: 16, height: 22), const Radius.circular(4)), _strokePaint);

