  void _drawFrontTireUltra(Canvas canvas, Offset center, double tw, double th, bool isLeft) {
    final RRect tireRect = RRect.fromRectAndRadius(Rect.fromCenter(center: center, width: tw, height: th), const Radius.circular(24));

    if (engine.brakeHeld && engine.speedKmh > 55) {
      final Offset discCenter = Offset(center.dx + (isLeft ? tw * 0.48 : -tw * 0.48), center.dy);
      final double dr = tw * 0.36;
      canvas.drawCircle(
        discCenter,
        dr,
        Paint()
          ..shader = const RadialGradient(colors: [Color(0xEEFF8A00), Color(0xAAFF3D00), Color(0x00FF3D00)]).createShader(Rect.fromCircle(center: discCenter, radius: dr)),
      );
    }

    canvas.drawRRect(
      tireRect,
      Paint()
        ..isAntiAlias = true
        ..shader = const LinearGradient(
          begin: Alignment.centerLeft,
          end: Alignment.centerRight,
          stops: [0.0, 0.18, 0.48, 0.78, 1.0],
          colors: [Color(0xFF07080B), Color(0xFF212630), Color(0xFF444D5E), Color(0xFF1D222B), Color(0xFF07080B)],
        ).createShader(tireRect.outerRect),
    );

    if (engine.speedKmh > 5) {
      final double phase = (engine.playerDist * 0.75) % 1.0;
      _strokePaint..color = const Color(0x30000000)..strokeWidth = 4.2;
