      pi * 0.68,
      false,
      _strokePaint,
    );

    _strokePaint..color = const Color(0xFFE10600)..strokeWidth = 4.0;
    canvas.drawArc(
      Rect.fromCenter(center: Offset(center.dx + dir * tw * 0.24, center.dy), width: tw * 0.47, height: th * 0.70),
