  void _drawButterflyWheelUltra(
    Canvas canvas,
    double cx,
    double cy,
    double w,
    double h,
    Paint carbonPaint,
  ) {
    final bool ersOn = engine.ersActive;
    final int rpm = engine.rpm;
    final int gear = engine.gear;

    canvas.save();
    canvas.translate(cx, cy);
    canvas.rotate(engine.steerAngle * 0.46 + engine.spinYaw * 0.5);

    final double swW = (w * 0.40).clamp(228.0, 360.0).toDouble();
    final double swH = (h * 0.325).clamp(126.0, 192.0).toDouble();

    _fillPaint.color = const Color(0xFF28303D);
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(-swW * 0.53, -swH * 0.26, swW * 0.14, swH * 0.14), const Radius.circular(6)), _fillPaint);
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(swW * 0.39, -swH * 0.26, swW * 0.14, swH * 0.14), const Radius.circular(6)), _fillPaint);

    final Path wheelShape = Path()
      ..moveTo(-swW * 0.42, -swH * 0.47)
      ..lineTo(-swW * 0.24, -swH * 0.47)
      ..lineTo(-swW * 0.18, -swH * 0.37)
      ..lineTo(swW * 0.18, -swH * 0.37)
      ..lineTo(swW * 0.24, -swH * 0.47)
      ..lineTo(swW * 0.42, -swH * 0.47)
      ..quadraticBezierTo(swW * 0.52, -swH * 0.45, swW * 0.50, -swH * 0.12)
      ..lineTo(swW * 0.47, swH * 0.37)
      ..quadraticBezierTo(swW * 0.44, swH * 0.49, swW * 0.24, swH * 0.47)
      ..lineTo(-swW * 0.24, swH * 0.47)
      ..quadraticBezierTo(-swW * 0.44, swH * 0.49, -swW * 0.47, swH * 0.37)
      ..lineTo(-swW * 0.50, -swH * 0.12)
      ..quadraticBezierTo(-swW * 0.52, -swH * 0.45, -swW * 0.42, -swH * 0.47)
      ..close();

    canvas.drawPath(wheelShape, carbonPaint);
    _strokePaint..color = const Color(0xFF5D6B82)..strokeWidth = 2.4;
    canvas.drawPath(wheelShape, _strokePaint);

    final double rpmRatio = ((rpm - 5800) / 8400.0).clamp(0.0, 1.0).toDouble();
    const int ledCount = 15;
    for (int i = 0; i < ledCount; i++) {
      final bool lit = (i / ledCount) < rpmRatio;
      final Color ledColor = i < 5
          ? const Color(0xFF00E676)
          : (i < 10 ? const Color(0xFFFF1744) : const Color(0xFF2979FF));
      final double lx = -swW * 0.22 + (i * (swW * 0.44 / (ledCount - 1)));
      final Offset lc = Offset(lx, -swH * 0.29);
      if (lit) {
        canvas.drawCircle(
          lc,
          6.5,
          Paint()..shader = RadialGradient(colors: [ledColor.withAlpha(185), ledColor.withAlpha(0)]).createShader(Rect.fromCircle(center: lc, radius: 6.5)),
        );
      }
      _fillPaint.color = lit ? ledColor : const Color(0xFF202530);
      canvas.drawCircle(lc, 2.8, _fillPaint);
    }

    final Rect lcdRect = Rect.fromCenter(center: Offset(0, -swH * 0.01), width: swW * 0.45, height: swH * 0.45);
    _fillPaint.color = const Color(0xFF04060A);
    canvas.drawRRect(RRect.fromRectAndRadius(lcdRect, const Radius.circular(6)), _fillPaint);
    _strokePaint..color = ersOn ? const Color(0xFF00E5FF) : const Color(0xFF425169)..strokeWidth = 1.7;
    canvas.drawRRect(RRect.fromRectAndRadius(lcdRect, const Radius.circular(6)), _strokePaint);

    _drawCenteredText(canvas, '$gear', Offset(0, -swH * 0.025), swH * 0.225, Colors.white, FontWeight.w900);
    _drawCenteredText(canvas, '${engine.speedKmh.toInt()}', Offset(-swW * 0.145, -swH * 0.13), swH * 0.102, const Color(0xFF00E676), FontWeight.w900);
    _drawCenteredText(canvas, engine.phase == SessionPhase.qualifying ? 'Q1' : 'P${engine.currentPosition}', Offset(swW * 0.145, -swH * 0.13), swH * 0.09, const Color(0xFFFFD54F), FontWeight.w900);
    _drawCenteredText(canvas, engine.phase == SessionPhase.qualifying ? '1 LAP' : 'L${engine.currentLap}/5', Offset(swW * 0.145, swH * 0.04), swH * 0.072, Colors.white70, FontWeight.bold);
    _drawCenteredText(
      canvas,
      ersOn ? 'ERS BOOST' : (engine.playerInSlipstream ? 'SLIPSTREAM' : '$rpm RPM'),
      Offset(0, swH * 0.11),
      swH * 0.075,
      ersOn ? const Color(0xFF00E5FF) : (engine.playerInSlipstream ? const Color(0xFF69F0AE) : const Color(0xFF94A3B8)),
      FontWeight.bold,
    );

    final double barW = lcdRect.width - 12;
    _fillPaint.color = const Color(0xFF1E293B);
    canvas.drawRect(Rect.fromLTWH(lcdRect.left + 6, lcdRect.bottom - 6, barW, 3.4), _fillPaint);
    _fillPaint.color = ersOn ? const Color(0xFF00E5FF) : const Color(0xFFFFD600);
    canvas.drawRect(Rect.fromLTWH(lcdRect.left + 6, lcdRect.bottom - 6, barW * (engine.ersCharge / 100.0), 3.4), _fillPaint);

    const List<Color> knobColors = [Color(0xFFE53935), Color(0xFF43A047), Color(0xFFFFB300)];
    for (int k = 0; k < 3; k++) {
      final double kx = (k - 1) * (swW * 0.115);
      final Offset kc = Offset(kx, swH * 0.34);
      canvas.drawCircle(
        kc,
        swH * 0.088,
        UltraTextures.brushedMetalShader != null
            ? (Paint()..isAntiAlias = true..shader = UltraTextures.brushedMetalShader)
            : (Paint()..isAntiAlias = true..color = const Color(0xFF94A3B8)),
      );
      _fillPaint.color = knobColors[k];
      canvas.drawCircle(kc, swH * 0.072, _fillPaint);
      _fillPaint.color = const Color(0xFF13171F);
      canvas.drawCircle(kc, swH * 0.032, _fillPaint);
    }

    _drawWheelButton(canvas, Offset(-swW * 0.33, -swH * 0.24), const Color(0xFF29B6F6));
    _drawWheelButton(canvas, Offset(swW * 0.33, -swH * 0.24), const Color(0xFFFFCA28));
    _drawWheelButton(canvas, Offset(-swW * 0.31, -swH * 0.04), const Color(0xFFEF5350));
    _drawWheelButton(canvas, Offset(swW * 0.31, -swH * 0.04), const Color(0xFF66BB6A));
    _drawWheelButton(canvas, Offset(-swW * 0.29, swH * 0.16), const Color(0xFFAB47BC));
    _drawWheelButton(canvas, Offset(swW * 0.29, swH * 0.16), const Color(0xFFFF7043));

    _drawRacingGloveUltra(canvas, swW, swH, true);
    _drawRacingGloveUltra(canvas, swW, swH, false);

    canvas.restore();
  }

  void _drawWheelButton(Canvas canvas, Offset center, Color color) {
    _fillPaint.color = const Color(0xFF0D1016);
    canvas.drawCircle(center, 6.4, _fillPaint);
    _fillPaint.color = color;
    canvas.drawCircle(center, 4.6, _fillPaint);
    _fillPaint.color = const Color(0xAAFFFFFF);
    canvas.drawCircle(Offset(center.dx - 1.3, center.dy - 1.3), 1.5, _fillPaint);
  }

  void _drawRacingGloveUltra(Canvas canvas, double swW, double swH, bool isLeft) {
    final TeamLivery livery = engine.livery;
    final double s = isLeft ? -1.0 : 1.0;
    final Rect palmRect = Rect.fromCenter(center: Offset(s * swW * 0.45, swH * 0.16), width: swW * 0.23, height: swH * 0.64);
    final Paint gloveShader = Paint()
      ..isAntiAlias = true
      ..shader = LinearGradient(
        begin: isLeft ? Alignment.centerLeft : Alignment.centerRight,
        end: isLeft ? Alignment.centerRight : Alignment.centerLeft,
        colors: [
          Color.lerp(livery.gloveColor, Colors.black, 0.38)!,
          livery.gloveColor,
          Color.lerp(livery.gloveColor, Colors.white, 0.18)!,
        ],
      ).createShader(palmRect);

    canvas.drawRRect(RRect.fromRectAndRadius(palmRect, const Radius.circular(20)), gloveShader);

    final RRect thumb = RRect.fromRectAndRadius(
      Rect.fromCenter(center: Offset(s * swW * 0.36, -swH * 0.02), width: swW * 0.135, height: swH * 0.195),
      const Radius.circular(10),
    );
    canvas.drawRRect(thumb, gloveShader);
    _strokePaint..color = const Color(0x55000000)..strokeWidth = 1.6;
    canvas.drawRRect(thumb, _strokePaint);

    _strokePaint..color = const Color(0x3DFFFFFF)..strokeWidth = 1.9;
    canvas.drawLine(Offset(s * swW * 0.41, swH * 0.04), Offset(s * swW * 0.49, swH * 0.24), _strokePaint);
    _strokePaint..color = livery.secondary.withAlpha(175)..strokeWidth = 2.6;
    canvas.drawLine(Offset(s * swW * 0.37, swH * 0.36), Offset(s * swW * 0.53, swH * 0.36), _strokePaint);
  }

  void _drawChaseCarUltra(Canvas canvas, double w, double h) {
    final TeamLivery livery = engine.livery;
    final bool ersOn = engine.ersActive;

    canvas.save();
    canvas.translate(w * 0.5, h * 0.80);
    canvas.rotate(engine.steerAngle * 0.065 + engine.spinYaw * 0.45);

    final Rect shad = Rect.fromCenter(center: const Offset(0, 14), width: 196, height: 32);
    canvas.drawOval(shad, Paint()..shader = const RadialGradient(colors: [Color(0xDD000000), Color(0x00000000)]).createShader(shad));
    _fillPaint.color = const Color(0xFF13161C);
    canvas.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(-84, -24, 30, 46), const Radius.circular(6)), _fillPaint);
    canvas.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(54, -24, 30, 46), const Radius.circular(6)), _fillPaint);
    _fillPaint.color = const Color(0xFF181C24);
    canvas.drawRect(const Rect.fromLTWH(-46, 2, 92, 14), _fillPaint);

    final Path body = Path()
      ..moveTo(-56, 4)
      ..lineTo(-35, -42)
      ..lineTo(35, -42)
      ..lineTo(56, 4)
      ..close();
    canvas.drawPath(
      body,
      Paint()
        ..isAntiAlias = true
        ..shader = LinearGradient(begin: Alignment.topCenter, end: Alignment.bottomCenter, colors: [livery.primaryLight, livery.primary, livery.primaryDark])
            .createShader(const Rect.fromLTWH(-56, -42, 112, 46)),
    );

    _fillPaint.color = const Color(0xFF1A1D24);
    canvas.drawRRect(RRect.fromRectAndRadius(const Rect.fromLTWH(-12, -55, 24, 24), const Radius.circular(10)), _fillPaint);
    _fillPaint.color = const Color(0xFFFF1744);
    canvas.drawRect(const Rect.fromLTWH(-4, -2, 8, 10), _fillPaint);
    _fillPaint.color = ersOn ? const Color(0xFF00E5FF) : livery.secondary;
    canvas.drawRRect(RRect.fromRectAndRadius(Rect.fromLTWH(-62, ersOn ? -50 : -42, 124, ersOn ? 7 : 13), const Radius.circular(3)), _fillPaint);
    canvas.restore();
  }

  void _drawCenteredText(Canvas canvas, String text, Offset center, double fontSize, Color color, FontWeight weight) {
    final TextPainter tp = TextPainter(
      text: TextSpan(text: text, style: TextStyle(color: color, fontSize: fontSize, fontWeight: weight)),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, Offset(center.dx - tp.width * 0.5, center.dy - tp.height * 0.5));
  }

  @override
  bool shouldRepaint(covariant F1UltraSmoothPainter oldDelegate) => false;
}

