package com.apexlife.apex_life_f1

import android.media.AudioAttributes
import android.media.AudioFormat
import android.media.AudioManager
import android.media.AudioTrack
import io.flutter.embedding.android.FlutterActivity
import io.flutter.embedding.engine.FlutterEngine
import io.flutter.plugin.common.MethodChannel
import kotlin.math.PI
import kotlin.math.exp
import kotlin.math.floor
import kotlin.math.max
import kotlin.math.min
import kotlin.math.sin
import kotlin.math.tanh
import kotlin.random.Random

class MainActivity : FlutterActivity() {
    private val channelName = "f1_audio"
    private var synth: F1V6PowerAudioEngine? = null

    override fun configureFlutterEngine(flutterEngine: FlutterEngine) {
        super.configureFlutterEngine(flutterEngine)
        val audioEngine = F1V6PowerAudioEngine()
        synth = audioEngine

        MethodChannel(flutterEngine.dartExecutor.binaryMessenger, channelName)
            .setMethodCallHandler { call, result ->
                when (call.method) {
                    "update" -> {
                        val rpm = (call.argument<Number>("rpm")?.toDouble()) ?: 4200.0
                        val speed = (call.argument<Number>("speed")?.toDouble()) ?: 0.0
                        val throttle = call.argument<Boolean>("throttle") ?: false
                        val brake = call.argument<Boolean>("brake") ?: false
                        val ers = call.argument<Boolean>("ers") ?: false
                        val offTrack = call.argument<Boolean>("offTrack") ?: false
                        val onKerb = call.argument<Boolean>("onKerb") ?: false
                        val slip = (call.argument<Number>("slip")?.toDouble()) ?: 0.0
                        val active = call.argument<Boolean>("active") ?: false
                        val muted = call.argument<Boolean>("muted") ?: false
                        audioEngine.updateState(
                            rpm = rpm,
                            speed = speed,
                            throttle = throttle,
                            brake = brake,
                            ers = ers,
                            offTrack = offTrack,
                            onKerb = onKerb,
                            slip = slip,
                            active = active,
                            muted = muted
                        )
                        result.success(null)
                    }
                    "event" -> {
                        val type = call.argument<String>("type") ?: ""
                        val intensity = (call.argument<Number>("intensity")?.toDouble()) ?: 1.0
                        audioEngine.triggerEvent(type, intensity)
                        result.success(null)
                    }
                    "stop" -> {
                        audioEngine.silence()
                        result.success(null)
                    }
                    else -> result.notImplemented()
                }
            }
    }

    override fun onPause() {
        synth?.setLifecyclePaused(true)
        super.onPause()
    }

    override fun onResume() {
        super.onResume()
        synth?.setLifecyclePaused(false)
    }

    override fun onDestroy() {
        synth?.release()
        synth = null
        super.onDestroy()
    }
}

private class F1V6PowerAudioEngine {
    private val sampleRate = 44100
    private val twoPi = 2.0 * PI

    @Volatile private var running = false
    @Volatile private var lifecyclePaused = false
    @Volatile private var muted = false
    @Volatile private var engineActive = false

    @Volatile private var targetRpm = 4200.0
    @Volatile private var targetSpeed = 0.0
    @Volatile private var targetThrottle = 0.0
    @Volatile private var targetBrake = 0.0
    @Volatile private var targetErs = 0.0
    @Volatile private var targetOffTrack = 0.0
    @Volatile private var targetOnKerb = 0.0
    @Volatile private var targetSlip = 0.0

    @Volatile private var crashEnv = 0.0
    @Volatile private var crashLowPitch = 96.0
    @Volatile private var upshiftCutEnv = 0.0
    @Volatile private var downshiftBarkEnv = 0.0
    @Volatile private var ersBoostEnv = 0.0
    @Volatile private var cueEnv = 0.0
    @Volatile private var cueFreq = 240.0
    @Volatile private var cueIsDouble = false

    private var audioThread: Thread? = null

    fun setLifecyclePaused(paused: Boolean) {
        lifecyclePaused = paused
    }

    fun silence() {
        engineActive = false
        targetThrottle = 0.0
        targetBrake = 0.0
        targetErs = 0.0
        targetOffTrack = 0.0
        targetOnKerb = 0.0
        targetSlip = 0.0
    }

    fun updateState(
        rpm: Double,
        speed: Double,
        throttle: Boolean,
        brake: Boolean,
        ers: Boolean,
        offTrack: Boolean,
        onKerb: Boolean,
        slip: Double,
        active: Boolean,
        muted: Boolean
    ) {
        this.muted = muted
        this.engineActive = active
        this.targetRpm = rpm.coerceIn(3800.0, 14500.0)
        this.targetSpeed = speed.coerceIn(0.0, 380.0)
        this.targetThrottle = if (throttle) 1.0 else 0.0
        this.targetBrake = if (brake && speed > 45.0) 1.0 else 0.0
        this.targetErs = if (ers) 1.0 else 0.0
        this.targetOffTrack = if (offTrack && speed > 18.0) 1.0 else 0.0
        this.targetOnKerb = if (onKerb && speed > 35.0) 1.0 else 0.0
        this.targetSlip = if (!offTrack && speed > 55.0) slip.coerceIn(0.0, 1.0) else 0.0

        if (active && !muted) {
            ensureStarted()
        }
    }

    fun triggerEvent(type: String, intensity: Double) {
        if (muted || lifecyclePaused) return
        ensureStarted()
        when (type) {
            "upshift" -> {
                upshiftCutEnv = 1.0
            }
            "downshift" -> {
                downshiftBarkEnv = 1.0
            }
            "shift" -> {
                upshiftCutEnv = 0.9
            }
            "ers" -> {
                ersBoostEnv = 0.95
            }
            "crash" -> {
                crashLowPitch = 96.0
                crashEnv = max(crashEnv, intensity.coerceIn(0.50, 1.0))
            }
            "light" -> {
                cueFreq = 220.0
                cueIsDouble = false
                cueEnv = 0.50
            }
            "go" -> {
                cueFreq = 440.0
                cueIsDouble = true
                cueEnv = 0.68
            }
            "lap" -> {
                cueFreq = 392.0
                cueIsDouble = true
                cueEnv = 0.45
            }
            "finish" -> {
                cueFreq = 523.25
                cueIsDouble = true
                cueEnv = 0.60
            }
        }
    }

    @Synchronized
    private fun ensureStarted() {
        if (running) return
        running = true
        val t = Thread({ runAudioLoop() }, "F1V6PowerAudioThread")
        t.priority = Thread.MAX_PRIORITY
        t.start()
        audioThread = t
    }

    @Synchronized
    fun release() {
        running = false
        try {
            audioThread?.join(250)
        } catch (_: Throwable) {
        }
        audioThread = null
    }

    private fun runAudioLoop() {
        var track: AudioTrack? = null
        try {
            val minBuf = AudioTrack.getMinBufferSize(
                sampleRate,
                AudioFormat.CHANNEL_OUT_MONO,
                AudioFormat.ENCODING_PCM_16BIT
            )
            val bufBytes = max(minBuf * 2, 4096)
            val attrs = AudioAttributes.Builder()
                .setUsage(AudioAttributes.USAGE_GAME)
                .setContentType(AudioAttributes.CONTENT_TYPE_SONIFICATION)
                .build()
            val format = AudioFormat.Builder()
                .setEncoding(AudioFormat.ENCODING_PCM_16BIT)
                .setSampleRate(sampleRate)
                .setChannelMask(AudioFormat.CHANNEL_OUT_MONO)
                .build()
            track = AudioTrack(
                attrs,
                format,
                bufBytes,
                AudioTrack.MODE_STREAM,
                AudioManager.AUDIO_SESSION_ID_GENERATE
            )
            if (track.state != AudioTrack.STATE_INITIALIZED) {
                running = false
                return
            }
            track.play()

            val chunkSize = 1024
            val buffer = ShortArray(chunkSize)
            val rng = Random(202607)

            // Twin-bank V6 per-cylinder combustion tolerances
            val imbA = doubleArrayOf(1.00, 0.91, 1.07)
            val imbB = doubleArrayOf(0.94, 1.05, 0.92)

            // Physical exhaust collector delay-line resonator (256-sample circular buffer)
            val delayBuf = DoubleArray(256)
            var dIdx = 0

            var curRpm = 4200.0
            var curSpeed = 0.0
            var curThrottle = 0.0
            var curBrake = 0.0
            var curErs = 0.0
            var curOffTrack = 0.0
            var curKerb = 0.0
            var curSlip = 0.0
            var masterGain = 0.0

            // Twin-bank V6 combustion & 3-band exhaust formant filter states
            var crankPhase = 0.0
            var prevCylA = -1
            var prevCylB = -1
            var jitA = 1.0
            var jitB = 1.0
            var lowLp = 0.0
            var bodyLp = 0.0
            var bodyBp = 0.0
            var raspLp = 0.0
            var raspBp = 0.0
            var intLp = 0.0
            var intBp = 0.0
            var outLp = 0.0
            var dcX = 0.0
            var dcY = 0.0
            var popEnv = 0.0
            var popPhase = 0.0

            // Road, wind, tire scrub, kerb, gravel, brakes
            var roadLp1 = 0.0
            var roadLp2 = 0.0
            var windLp = 0.0
            var slipLp = 0.0
            var slipBp = 0.0
            var brakeLp = 0.0
            var brakeBp = 0.0
            var gravelLp = 0.0
            var kerbPhase = 0.0
            var kerbThudLp = 0.0

            // Crash & race cue states
            var crashPhase = 0.0
            var crashLp = 0.0
            var cuePhase = 0.0

            val dt = 1.0 / sampleRate.toDouble()

            while (running) {
                val activeNow = !muted && !lifecyclePaused && (engineActive || cueEnv > 0.004 || crashEnv > 0.004)
                val targetGain = if (activeNow) 0.84 else 0.0

                if (!activeNow && masterGain < 0.002) {
                    try {
                        Thread.sleep(25)
                    } catch (_: Throwable) {
                    }
                    continue
                }

                for (i in 0 until chunkSize) {
                    curRpm += (targetRpm - curRpm) * 0.0042
                    curSpeed += (targetSpeed - curSpeed) * 0.0030
                    curThrottle += (targetThrottle - curThrottle) * 0.0055
                    curBrake += (targetBrake - curBrake) * 0.0065
                    curErs += (targetErs - curErs) * 0.0055
                    curOffTrack += (targetOffTrack - curOffTrack) * 0.0065
                    curKerb += (targetOnKerb - curKerb) * 0.011
                    curSlip += (targetSlip - curSlip) * 0.0065
                    masterGain += (targetGain - masterGain) * 0.0025

                    var sample = 0.0

                    if (engineActive) {
                        // =====================================================
                        // 1. TWIN-BANK F1 V6 TURBO COMBUSTION + EXHAUST PIPE DSP
                        // =====================================================
                        val rpmNorm = ((curRpm - 3800.0) / 9700.0).coerceIn(0.0, 1.0)
                        val fCrank = (curRpm / 60.0) * (1.0 + downshiftBarkEnv * 0.08)
                        crankPhase += fCrank * dt
                        if (crankPhase >= 2.0) crankPhase -= 2.0

                        // Left V6 Bank (3 cylinders over 2 crank revs = 1.5 * fCrank)
                        val posA = crankPhase * 1.5
                        val cylA = floor(posA).toInt() % 3
                        val fracA = posA - floor(posA)
                        if (cylA != prevCylA) {
                            prevCylA = cylA
                            jitA = imbA[if (cylA in 0..2) cylA else 0] * (0.86 + 0.28 * rng.nextDouble())
                            // Off-throttle exhaust overrun crackles/burbles
                            if (curThrottle < 0.14 && curRpm > 6400.0 && rng.nextDouble() < 0.22) {
                                popEnv = max(popEnv, 0.35 + rng.nextDouble() * 0.42)
                            }
                        }

                        // Right V6 Bank (staggered 180 deg + subtle 3% exhaust runner asymmetry for gritty V6 growl!)
                        val posB = (crankPhase * 1.5 + 0.53) % 3.0
                        val cylB = floor(posB).toInt() % 3
                        val fracB = posB - floor(posB)
                        if (cylB != prevCylB) {
                            prevCylB = cylB
                            jitB = imbB[if (cylB in 0..2) cylB else 0] * (0.86 + 0.28 * rng.nextDouble())
                        }

                        val activeLoad = (curThrottle + curErs * 0.25 + downshiftBarkEnv * 0.70 + ersBoostEnv * 0.30).coerceIn(0.0, 1.35)
                        val sharp = 3.8 + activeLoad * 3.4 + rpmNorm * 1.6

                        val pA = if (fracA < 0.08) fracA / 0.08 else exp(-(fracA - 0.08) * sharp)
                        val pB = if (fracB < 0.08) fracB / 0.08 else exp(-(fracB - 0.08) * sharp)

                        val v6Pulses = ((pA * 2.0 - 0.42) * jitA) + ((pB * 2.0 - 0.42) * jitB * 0.88)

                        // Deep crankshaft & V6 firing-order sub-harmonics (guttural punch)
                        val ang = crankPhase * PI
                        val mechLow = sin(ang * 2.0) * 0.34 + sin(ang * 3.0) * 0.44 + sin(ang * 1.0) * 0.16

                        // Hot exhaust gas turbulence noise modulated directly by cylinder pressure
                        val wn = rng.nextDouble() * 2.0 - 1.0
                        val peakCyl = max(pA, pB)
                        val gasRoar = wn * (0.18 + 0.82 * peakCyl) * (0.28 + 0.72 * activeLoad)

                        // Seamless-shift ignition cut + gunshot exhaust pop on upshift
                        var cutGain = 1.0
                        var shiftBlast = 0.0
                        if (upshiftCutEnv > 0.005) {
                            cutGain = if (upshiftCutEnv > 0.46) 0.22 else 1.0
                            if (upshiftCutEnv in 0.22..0.52) {
                                shiftBlast = (rng.nextDouble() * 2.0 - 1.0) * upshiftCutEnv * 0.75
                            }
                            upshiftCutEnv *= 0.9990
                            if (upshiftCutEnv < 0.005) upshiftCutEnv = 0.0
                        }
                        if (downshiftBarkEnv > 0.005) {
                            downshiftBarkEnv *= 0.9992
                            if (downshiftBarkEnv < 0.005) downshiftBarkEnv = 0.0
                        }
                        if (ersBoostEnv > 0.005) {
                            ersBoostEnv *= 0.9993
                            if (ersBoostEnv < 0.005) ersBoostEnv = 0.0
                        }

                        val collector = (v6Pulses * (0.55 + 0.55 * activeLoad) +
                            mechLow * (0.55 + 0.35 * activeLoad) +
                            gasRoar * 0.55) * cutGain + shiftBlast

                        // Asymmetric exhaust waveshaping (aggressive harmonic saturation)
                        val drive = 1.35 + activeLoad * 1.40 + rpmNorm * 0.65
                        val bias = 0.18 * activeLoad
                        val shaped = tanh((collector + bias) * drive) - tanh(bias * drive)

                        // Physical Exhaust Pipe Delay-Line Comb Resonator (1.5ms..2.5ms)
                        val delaySamps = (68.0 + (1.0 - rpmNorm) * 44.0).toInt()
                        val readIdx = (dIdx - delaySamps) and 255
                        val delayed = delayBuf[readIdx]
                        val pipeSig = shaped + delayed * (0.28 + 0.18 * activeLoad)
                        delayBuf[dIdx] = (shaped + delayed * 0.38).coerceIn(-1.2, 1.2)
                        dIdx = (dIdx + 1) and 255

                        // 3-Band Sculpted V6 Exhaust EQ:
                        // Band 1: Deep V6 Sub-Growl (LPF 260..500 Hz)
                        val fLow = 260.0 + rpmNorm * 240.0
                        val aLow = min(0.35, (twoPi * fLow) / (twoPi * fLow + sampleRate))
                        lowLp += (pipeSig - lowLp) * aLow

                        // Band 2: Muscular V6 Exhaust Body Formant (SVF BPF 360..900 Hz)
                        val fBody = 360.0 + rpmNorm * 540.0
                        val cBody = min(0.32, 2.0 * sin(PI * fBody / sampleRate))
                        val bHp = pipeSig - bodyLp - 0.65 * bodyBp
                        bodyBp += cBody * bHp
                        bodyLp += cBody * bodyBp

                        // Band 3: Aggressive Raspy V6 F1 Bite (SVF BPF 1050..2300 Hz under throttle!)
                        val fRasp = 1050.0 + rpmNorm * 1250.0
                        val cRasp = min(0.45, 2.0 * sin(PI * fRasp / sampleRate))
                        val rHp = pipeSig - raspLp - 0.72 * raspBp
                        raspBp += cRasp * rHp
                        raspLp += cRasp * raspBp

                        // Band 4: Airbox Intake Induction Roar (480..1300 Hz on open throttle)
                        val wn2 = rng.nextDouble() * 2.0 - 1.0
                        val fInt = 480.0 + rpmNorm * 820.0
                        val cInt = min(0.35, 2.0 * sin(PI * fInt / sampleRate))
                        val iHp = wn2 - intLp - 0.80 * intBp
                        intBp += cInt * iHp
                        intLp += cInt * intBp
                        val intakeSig = intBp * (0.14 + 0.36 * activeLoad) * (0.35 + 0.65 * peakCyl)

                        // Off-throttle exhaust burble pop
                        var popSig = 0.0
                        if (popEnv > 0.005) {
                            popPhase += twoPi * 105.0 * dt
                            if (popPhase > twoPi) popPhase -= twoPi
                            popSig = (sin(popPhase) * 0.50 + (rng.nextDouble() * 2.0 - 1.0) * 0.50) * popEnv * 0.34
                            popEnv *= 0.9984
                            if (popEnv < 0.005) popEnv = 0.0
                        }

                        val engMix = lowLp * (0.58 + 0.16 * activeLoad) +
                            bodyBp * (0.42 + 0.34 * activeLoad) +
                            raspBp * (0.10 + 0.44 * activeLoad * (0.35 + 0.65 * rpmNorm)) +
                            intakeSig + popSig

                        // Warmth ceiling LPF + DC blocker
                        outLp += (engMix - outLp) * 0.36
                        val dcOut = outLp - dcX + 0.995 * dcY
                        dcX = outLp
                        dcY = dcOut

                        sample += dcOut * (0.54 + 0.24 * activeLoad)

                        // =====================================================
                        // 2. ASPHALT TIRE ROLL + WIND RUSH + CORNERING SCRUB
                        // =====================================================
                        val speedNorm = min(1.0, curSpeed / 330.0)
                        val nRoad = rng.nextDouble() * 2.0 - 1.0
                        roadLp1 += (nRoad - roadLp1) * (0.025 + 0.035 * speedNorm)
                        roadLp2 += (roadLp1 - roadLp2) * 0.08
                        sample += roadLp2 * (0.38 * speedNorm)

                        val nWind = rng.nextDouble() * 2.0 - 1.0
                        windLp += (nWind - windLp) * (0.035 + 0.08 * speedNorm)
                        sample += (windLp - roadLp2) * (0.26 * speedNorm * speedNorm)

                        if (curSlip > 0.04) {
                            val nSlip = rng.nextDouble() * 2.0 - 1.0
                            val slipHz = 560.0 + curSlip * 320.0 + speedNorm * 140.0
                            val fS = min(0.24, 2.0 * sin(PI * slipHz / sampleRate))
                            val sHp = nSlip - slipLp - 0.38 * slipBp
                            slipBp += fS * sHp
                            slipLp += fS * slipBp
                            sample += tanh(slipBp * 1.5) * curSlip * 0.25
                        }

                        // =====================================================
                        // 3. KERBS (PIANOS), GRAVEL & CARBON BRAKE HISS
                        // =====================================================
                        if (curKerb > 0.01) {
                            val kerbHz = 34.0 + curSpeed * 0.16
                            kerbPhase += kerbHz * dt
                            if (kerbPhase >= 1.0) kerbPhase -= 1.0
                            val rawThud = if (kerbPhase < 0.28) 1.0 else -0.35
                            kerbThudLp += (rawThud - kerbThudLp) * 0.045
                            sample += kerbThudLp * curKerb * 0.28
                        }

                        if (curOffTrack > 0.01) {
                            val rawG = rng.nextDouble() * 2.0 - 1.0
                            gravelLp += (rawG - gravelLp) * 0.10
                            val stoneHit = if (rng.nextDouble() < 0.035) (rng.nextDouble() * 2.0 - 1.0) * 0.45 else 0.0
                            sample += (gravelLp * 0.55 + stoneHit) * curOffTrack * 0.44
                        }

                        if (curBrake > 0.01) {
                            val nBrk = rng.nextDouble() * 2.0 - 1.0
                            val fB = min(0.22, 2.0 * sin(PI * (920.0 + speedNorm * 350.0) / sampleRate))
                            val bHp = nBrk - brakeLp - 0.55 * brakeBp
                            brakeBp += fB * bHp
                            brakeLp += fB * brakeBp
                            sample += brakeBp * curBrake * 0.14
                        }
                    }

                    // =========================================================
                    // 4. DEEP COLLISION THUD + CARBON CRUNCH
                    // =========================================================
                    if (crashEnv > 0.004) {
                        crashPhase += twoPi * crashLowPitch * dt
                        if (crashPhase > twoPi) crashPhase -= twoPi
                        crashLowPitch = max(34.0, crashLowPitch * 0.9997)
                        val nCr = rng.nextDouble() * 2.0 - 1.0
                        crashLp += (nCr - crashLp) * 0.16
                        sample += (sin(crashPhase) * 0.62 + crashLp * 0.55) * crashEnv * 0.72
                        crashEnv *= 0.99962
                        if (crashEnv < 0.004) crashEnv = 0.0
                    }

                    // =========================================================
                    // 5. SHORT WARM START-LIGHT / LAP TELEMETRY CUE
                    // =========================================================
                    if (cueEnv > 0.004) {
                        cuePhase += twoPi * cueFreq * dt
                        if (cuePhase > twoPi) cuePhase -= twoPi
                        val tone = if (cueIsDouble) {
                            sin(cuePhase) * 0.65 + sin(cuePhase * 1.5) * 0.35
                        } else {
                            sin(cuePhase)
                        }
                        sample += tone * cueEnv * 0.16
                        cueEnv *= 0.9991
                        if (cueEnv < 0.004) cueEnv = 0.0
                    }

                    val outVal = tanh(sample * masterGain * 1.15).coerceIn(-0.96, 0.96)
                    buffer[i] = (outVal * 32767.0).toInt().toShort()
                }

                track.write(buffer, 0, chunkSize)
            }
        } catch (_: Throwable) {
        } finally {
            running = false
            try {
                track?.stop()
                track?.release()
            } catch (_: Throwable) {
            }
        }
    }
}
